window.COURSE_DATA={"meta":{"title":"Ttro Intro Engine","pagesPerLanguage":77,"pdfFile":"book.pdf","pdfTotalPages":154,"pdfLanguageBoundary":77},"chapters":[{"id":"guide","ja":"導入・データ管理","en":"Guide & data","color":"#2563eb"},{"id":"drawing","ja":"第1講 描画基盤","en":"Lesson 1 · Drawing foundation","color":"#2563eb"},{"id":"time","ja":"第2講 時間とEasing","en":"Lesson 2 · Time & easing","color":"#7c3aed"},{"id":"camera","ja":"第3講 CameraとShake","en":"Lesson 3 · Camera & shake","color":"#f59e0b"},{"id":"text","ja":"第4講 Text","en":"Lesson 4 · Text","color":"#14b8a6"},{"id":"background","ja":"第5講 Background","en":"Lesson 5 · Background","color":"#22c55e"},{"id":"effect","ja":"第6講 Effect","en":"Lesson 6 · Effect","color":"#ec4899"},{"id":"particle","ja":"第7講 Particle","en":"Lesson 7 · Particle","color":"#06b6d4"},{"id":"spline","ja":"第8講 Spline","en":"Lesson 8 · Spline","color":"#8b5cf6"},{"id":"end","ja":"仕上げ","en":"Finish","color":"#3b82f6"}],"lessons":[{"id":"p01","sourcePage":1,"chapter":"guide","tag":"INTRO","title":"Scratch イントロエンジン完全講座","subtitle":"V2を基礎から分解し、修正版の設計として再構成","body":["本書は、Scratchで高度なイントロを構成するための汎用エンジンを、機能ごとに分解して理解するための教科書です。完成品のV2 {TtroIntroEngine}.sb3を基準にしながら、コード量を減らすための圧縮と、機能そのものの原理を切り分けます。","重要なのは、個々のエフェクトを覚えることではなく、すべてを「時刻から状態を計算し、共通の描画系へ渡す」という一つの考え方で捉えることです。各章では、その機能が何を入力し、内部で何を計算し、どの値を次の機能へ渡すかを整理します。"],"keyPoints":["描画・時間・カメラ・文字・背景・Effect・Particle・Splineを一冊で整理","左：大枠と図解 右：教科書本文","V2の圧縮構造は残しつつ、意味のある名前で読み解く"],"formulas":[],"en":{"title":"Scratch Intro Engine - Complete Course","subtitle":"Decompose V2 into understandable systems and rebuild it as a cleaner design.","body":["This guide explains a reusable Scratch intro engine by separating rendering, time, camera, text, background, effects, particles, and splines into distinct systems. The central idea is to compute state from time and pass that state into a shared rendering pipeline instead of memorizing isolated effects."],"keyPoints":["This guide explains a reusable Scratch intro engine by separating rendering, time, camera, text, background, effects, particles, and splines into distinct systems.","The central idea is to compute state from time and pass that state into a shared rendering pipeline instead of memorizing isolated effects."]},"lab":null,"baseLessons":["l01"]},{"id":"p02","sourcePage":2,"chapter":"guide","tag":"INTRO","title":"全体構成","subtitle":"8つの機能を、依存関係に沿って理解する","body":["各定義は独立していません。StampはPosとVFX+Stampに依存し、PosはRotMatを利用します。Camera、Text、Background、Particle、Splineの多くはEasingを利用するため、時間基盤を先に理解する必要があります。","全体の依存関係は、描画基盤 → 時間管理 → Camera → Text → Background →Effect → Particle → Splineの順に追うと最も自然です。これはScratchのブロックを置く順番ではなく、概念上の前提関係を示しています。","Splineは依存が最も多く、制御点管理・補間・角度・Pen・カメラが揃って初めて全体像を説明できます。"],"keyPoints":["1 描画基盤：List / RotMat / Pos / Stamp","2 時間：Timer / Easing","3 Camera / Shake","4 Text"],"formulas":[],"en":{"title":"Overall architecture","subtitle":"Understand the eight systems in dependency order.","body":["The definitions are not independent. Stamp depends on Position and VFX Stamp, Position depends on rotation math, and many higher-level systems depend on Easing. Following the dependency order makes the engine easier to build, debug, and extend."],"keyPoints":["The definitions are not independent.","Stamp depends on Position and VFX Stamp, Position depends on rotation math, and many higher-level systems depend on Easing.","Following the dependency order makes the engine easier to build, debug, and extend."]},"lab":null,"baseLessons":["l02"]},{"id":"p03","sourcePage":3,"chapter":"guide","tag":"INTRO","title":"略称と記号","subtitle":"略称は初出で正式名称を確認し、その後は短い表記を統一して使う。","body":["BGはBackground、HSVはHue / Saturation / Value、VFXはVisual Effectsの略です。BPMはBeats Per Minute、IDはIdentifierを意味します。","Splineで使うIppやIpp cacheなどは固有のデータ名として扱い、途中で別の意味を与えません。表記を固定すると、定義名・引数名・解説の対応を追いやすくなります。"],"keyPoints":[],"formulas":[],"en":{"title":"Abbreviations and notation","subtitle":"Expand each abbreviation once, then use one consistent short form throughout the engine.","body":["BG means Background, HSV means Hue / Saturation / Value, and VFX means Visual Effects. BPM stands for Beats Per Minute, while ID is an identifier used to choose a variant or object type.","Spline-specific names such as Ipp and Ipp cache are treated as stable data-structure names rather than redefined abbreviations. Consistent terminology keeps definition names, arguments, diagrams, and explanations aligned."],"keyPoints":["Expand abbreviations at first use.","Keep the same short form in code, diagrams, and prose.","Treat Ipp and similar spline names as stable identifiers."]},"lab":null,"baseLessons":[]},{"id":"p04","sourcePage":4,"chapter":"guide","tag":"INTRO","title":"データの持ち方","subtitle":"変数を増やさず、意味が持続する状態と「その場の計算」を明確に分離する。","body":["長時間保持する必要がある値は変数にします。Timer、Camera X/Y、Camera Rotation / Zoomのように、次の処理でも意味が残る状態が対象です。","Easingの途中値、Positionの座標計算、Shakeの一時値、Particleの寿命や疑似乱数など、計算が終われば再利用できる値は*Listへ置きます。Splineでは大量の点列をIpp / Ipp cache / Spline posとして分離します。"],"keyPoints":[],"formulas":[],"en":{"title":"How the engine stores data","subtitle":"Separate persistent state from temporary calculations instead of turning every intermediate value into a variable.","body":["Use variables for values whose meaning must survive across operations: Timer, Camera X/Y, Camera Rotation, Camera Zoom, and other persistent state.","Use *List for intermediate values that can be reused after a calculation finishes, such as Easing progress, Position work values, Shake intermediates, and Particle lifetime or random calculations. Spline keeps its larger point data in dedicated Ipp, Ipp cache, and Spline pos lists."],"keyPoints":["Persistent state belongs in named variables.","Reusable intermediate calculations belong in *List.","Large spline point data stays in dedicated lists."]},"lab":null,"baseLessons":[]},{"id":"p05","sourcePage":5,"chapter":"guide","tag":"INTRO","title":"定義 List","subtitle":"Set / Add / Clear を1つの補助定義にまとめる","body":["最初にList定義を構成します。引数はn、set、addの3つです。nは*Listの何番を操作するか、setは新しい値、addは加算値です。","まず、setが空欄かを調べます。setもaddも空なら、その項目を空欄にします。setが空でaddだけ入っていれば、現在値にaddを足します。逆にsetが入っていてaddが空なら、単純にsetへ置き換えます。両方入っていればset+addを入れます。","この定義は後で何十回も使うので、先に用意しておきます。本資料では「番号へ値を書くための短縮ブロック」と捉えると理解しやすくなります。"],"keyPoints":["最初にList定義を構成します","引数はn、set、addの3つです","nは*Listの何番を操作するか、setは新しい値、addは加算値です"],"formulas":[],"en":{"title":"Definition: List","subtitle":"Combine Set, Add, and Clear into one compact helper.","body":["The List helper takes a slot number plus optional set and add values. It can clear a slot, add to the current value, replace it, or apply set+add. Because many definitions write temporary results to *List, this helper becomes a core building block."],"keyPoints":["The List helper takes a slot number plus optional set and add values.","It can clear a slot, add to the current value, replace it, or apply set+add.","Because many definitions write temporary results to *List, this helper becomes a core building block."]},"lab":null,"baseLessons":["l06"]},{"id":"p06","sourcePage":6,"chapter":"guide","tag":"INTRO","title":"*List の初期化と使い分け","subtitle":"150個の空要素を先に確保し、内部計算では使い終わった番号を再利用する。","body":["Scratchの「n番目を置き換える」は、その番号の要素が存在しなければ使えません。開始時に*Listを空にしてから空文字を150回追加し、1〜150番をいつでも書き換えられる状態にします。","番号は固定の意味そのものではなく衝突を避けるための運用規約です。1〜50は出力や定義間の受け渡し、51〜100は定義内の一時計算、101〜150はSplineなど大きな処理や予備領域として使うと整理しやすくなります。"],"keyPoints":[],"formulas":["1-50: output / hand-off","51-100: temporary work","101-150: large work / reserve"],"en":{"title":"Initializing and partitioning *List","subtitle":"Preallocate 150 slots, then reuse temporary indices after their calculations are complete.","body":["Scratch can replace item n only when that item already exists. At startup, clear *List and append 150 empty items so slots 1 through 150 are always writable.","The ranges are a collision-avoidance policy, not permanent meanings. A useful convention is 1-50 for outputs and hand-offs, 51-100 for temporary calculations inside a definition, and 101-150 for larger jobs such as Spline data or reserve space."],"keyPoints":["Preallocate slots before using “replace item n”.","Reuse temporary slots after their values are no longer needed.","Do not bind persistent state such as Camera X to arbitrary *List slots."]},"lab":"memory","baseLessons":[]},{"id":"p07","sourcePage":7,"chapter":"drawing","tag":"第1講","title":"描画基盤","subtitle":"「入力値 → Pos → VFX → Stamp」という一本道を作る","body":["第1講では、まずイントロエンジンの描画基盤を構成します。ここで完成させるのは、座標やサイズ、向き、コスチューム、色などを入力すると、最終的に1か所のStampから画面へ描画できる仕組みです。","順番はList、RotMat、VFX+Stamp、Pos、Stampです。これ以降のText、Effect、Particle、Splineは、直接スプライトを動かすのではなくStampを呼びます。","Allはこの時点では空の定義だけ構成します。シリーズを進めるたびに処理を追加する箱として使います。"],"keyPoints":["すべての素材の最後の描画をStampへ統一","座標処理と見た目処理を分離","後からカメラを入れても各機能を書き直さない","Allは空の箱だけ作る"],"formulas":[],"en":{"title":"Drawing foundation","subtitle":"Create one path from input values to Position, VFX, and Stamp.","body":["This lesson establishes a single rendering entrance. Position handles coordinates, VFX Stamp handles appearance, and Stamp performs the final draw. Higher-level systems call this shared pipeline instead of duplicating camera and effect logic."],"keyPoints":["This lesson establishes a single rendering entrance.","Position handles coordinates, VFX Stamp handles appearance, and Stamp performs the final draw.","Higher-level systems call this shared pipeline instead of duplicating camera and effect logic."]},"lab":null,"baseLessons":["l05"]},{"id":"p08","sourcePage":8,"chapter":"drawing","tag":"第1講","title":"定義 Rotate Position","subtitle":"点(x,y)を角度dだけ回転させる","body":["次はRotMatです。これは回転行列の計算を2行にまとめたものです。","回転後のxは、x×cos dからy×sin dを引きます。回転後のyは、x×sin dにy×cos dを足します。Scratchのsinとcosは角度を度数法で受け取るので、そのままdを入れられます。","本節では「点の位置を任意の角度だけ回転できる処理」と捉えれば十分です。第3講のCamera Rotationで、画面内のすべての座標を同じように回すために使います。","RotMatを実際に組みます。引数はx、y、dに加えて、結果を書き込むoutXとoutYです。","1本目のListでoutXへx cos dをSetし、-y sin dをAddします。2本目はoutYへx sin dをSetし、y cos dをAddします。","わざわざ戻り値の代わりにListへ書くのは、Scratchの自作ブロックが値を返す関数を標準では持たないためです。V2ではこのパターンをかなり多く使っています。"],"keyPoints":["次はRotMatです","これは回転行列の計算を2行にまとめたものです","回転後のxは、x×cos dからy×sin dを引きます(x', y')","RotMatを実際に組みます","引数はx、y、dに加えて、結果を書き込むoutXとoutYです","1本目のListでoutXへx cos dをSetし、-y sin dをAddします"],"formulas":["x' = x*cos(d) - y*sin(d)","y' = x*sin(d) + y*cos(d)"],"en":{"title":"Definition: Rotate Position","subtitle":"Rotate a point (x, y) by angle d.","body":["RotMat is a two-dimensional rotation matrix. Scratch trigonometric blocks use degrees, so the input angle can be used directly. The same operation later rotates every screen coordinate for camera rotation.","RotMat accepts x, y, angle, and two output-slot numbers. Because Scratch custom blocks do not normally return a value, the definition writes x' and y' into *List, letting the caller choose safe temporary storage."],"keyPoints":["RotMat is a two-dimensional rotation matrix.","Scratch trigonometric blocks use degrees, so the input angle can be used directly.","The same operation later rotates every screen coordinate for camera rotation.","RotMat accepts x, y, angle, and two output-slot numbers."]},"lab":"rotate","baseLessons":["l07","l08"]},{"id":"p09","sourcePage":9,"chapter":"drawing","tag":"第1講","title":"定義 VFX Stamp","subtitle":"Scratch標準エフェクトを設定して、最後に1回スタンプ","body":["VFX+Stampは、1回のStamp直前に色・明るさ・透明度を設定する最小描画単位です。色にはGlobalHue（V2: *List 50）を加え、イントロ全体の色相を一括でずらせるようにします。","VFX+Stamp自体は1回描画するだけですが、上位のStamp定義から複数回呼び出すことで、白成分・黒成分・色成分を重ねる表現へ拡張できます。"],"keyPoints":["色・明るさ・透明度を設定して1回Stamp","GlobalHue（V2: 50）を色相へ加算","上位Stampから複数回呼び出して色表現を合成"],"formulas":[],"en":{"title":"Definition: VFX Stamp","subtitle":"Apply Scratch visual effects, then stamp exactly once.","body":["VFX Stamp is the smallest visual rendering unit. It sets color, brightness, and transparency, adds the global hue offset, then stamps once. More complex looks are created by calling this unit multiple times from Stamp."],"keyPoints":["VFX Stamp is the smallest visual rendering unit.","It sets color, brightness, and transparency, adds the global hue offset, then stamps once.","More complex looks are created by calling this unit multiple times from Stamp."]},"lab":null,"baseLessons":["l09"]},{"id":"p10","sourcePage":10,"chapter":"drawing","tag":"第1講","title":"定義 Position","subtitle":"x/yをCameraからの相対座標へ変換し、RotationとZoomを適用","body":["Posでは、まずカメラを使う場合の座標変換を組みます。V2ではcam引数が空欄のときカメラを適用する作りです。","xからCamera Xを、yからCamera Yを引き、その相対座標をRotMatへ渡します。回転後の座標にZoomを掛けてgo toし、向きからCamera Rotationを引きます。サイズにもZoomを掛けます。","ここで重要なのは、カメラを素材ごとに書くのではなくPosへ集約していることです。以後Stampを使うものは、自動的に同じカメラ空間へ入ります。","camを使わない場合は、x、y、向き、サイズをそのまま使います。その後、最終サイズが100未満ならSiz hackという内部コスチュームへ一度切り替え、サイズを設定してから目的のコスチュームへ戻します。","V2ではPos hackとSiz hackという専用コスチュームを使い、Scratchのサイズ制限やコスチューム寸法による挙動を安定させています。最初の「1 ÷ 0」を利用するサイズ設定もそのハックの一部です。","これは補助的な実装なので、本資料では「大きさの限界で素材が正しく縮小・拡大できない場合に使う内部対策」と説明し、通常部分と分けて示します。"],"keyPoints":["Posでは、まずカメラを使う場合の座標変換を組みます","V2ではcam引数が空欄のときカメラを適用する作りです","xからCamera Xを、yからCamera Yを引き、その相対座標をRotMatへ渡します","Pos hack / Siz hack は内部処理用コスチューム","V2冒頭の set size to 1/0% はサイズ状態を大きく振るハック","本資料では「Scratchのサイズ制限対策」として別枠で説明"],"formulas":["localX = x - CamX","localY = y - CamY","(rx,ry) = RotMat(localX,localY,CamRot)","screen = (rx*Zoom, ry*Zoom)","direction = d - CamRot","size = s * Zoom"],"en":{"title":"Definition: Position","subtitle":"Convert world coordinates into screen coordinates using camera translation, rotation, and zoom.","body":["Position subtracts camera X/Y, rotates the relative vector, applies camera zoom, adjusts direction, and scales size. Centralizing this transform means every higher-level drawing feature automatically follows the same camera.","When camera processing is disabled, Position uses the input coordinates directly. V2 also contains costume-based size workarounds for Scratch limits; the web edition keeps those implementation hacks separate from the coordinate-transform principle."],"keyPoints":["Position subtracts camera X/Y, rotates the relative vector, applies camera zoom, adjusts direction, and scales size.","Centralizing this transform means every higher-level drawing feature automatically follows the same camera.","When camera processing is disabled, Position uses the input coordinates directly.","V2 also contains costume-based size workarounds for Scratch limits; the web edition keeps those implementation hacks separate from the coordinate-transform principle."]},"lab":null,"baseLessons":["l10","l11"]},{"id":"p11","sourcePage":11,"chapter":"drawing","tag":"第1講","title":"定義 Stamp","subtitle":"指定期間だけ描画し、まず位置状態を確定する","body":["Stamp本体の最初は時間条件です。t1が空欄なら開始制限なし、そうでなければTimerがt1を超えているときだけ描画します。t2も同様に、空欄なら終了制限なしです。","条件を満たしたら、まずPosを呼んで位置、向き、サイズ、コスチュームを確定します。その後に見た目の処理へ進みます。","この時間条件があることで、EffectやCoverのように「この区間だけ存在する素材」を、各機能側で毎回ifを書くことなくStampだけで制御できます。","Modeが入っている場合は、H、S、VをそのままVFX+Stampへ渡して1回描画します。これはEffectの二重レイヤーなどで使われます。","描画後にはグラフィック効果を消します。Scratchの効果はスプライトに残るので、ここを忘れると次のStampまで前の明るさや透明度が残ってしまいます。","e引数は、効果を保持する必要がある特殊ケースのためのスイッチとして使われています。通常は空欄にして、最後に必ずclear graphic effectsする、と理解しておくと安全です。"],"keyPoints":["Stamp本体の最初は時間条件です","t1が空欄なら開始制限なし、そうでなければTimerがt1を超えているときだけ描画します","t2も同様に、空欄なら終了制限なしです","Modeが入っている場合は、H、S、VをそのままVFX+Stampへ渡して1回描画します","これはEffectの二重レイヤーなどで使われます","描画後にはグラフィック効果を消します"],"formulas":[],"en":{"title":"Definition: Stamp","subtitle":"Render only inside the requested time interval and resolve position first.","body":["Stamp first checks optional start and end times. If the object is active, it calls Position to settle screen position, direction, size, and costume before applying visual layers. This removes repeated timing checks from higher-level features.","With Mode enabled, Stamp forwards H/S/V values directly to VFX Stamp for a single pass. After rendering, effects are normally cleared because Scratch visual effects persist on the sprite and would otherwise affect later stamps."],"keyPoints":["Stamp first checks optional start and end times.","If the object is active, it calls Position to settle screen position, direction, size, and costume before applying visual layers.","This removes repeated timing checks from higher-level features.","With Mode enabled, Stamp forwards H/S/V values directly to VFX Stamp for a single pass."]},"lab":null,"baseLessons":["l12","l14"]},{"id":"p12","sourcePage":12,"chapter":"drawing","tag":"第1講","title":"HSVを多重Stampで作る","subtitle":"Mode空欄時は白/黒レイヤーを重ねて見た目を作る","body":["StampのModeが空欄の場合、V2は1回の標準エフェクトだけで終わらず、同じ素材を複数回スタンプします。","基本色をHで描いたあと、明るいレイヤーを透明度付きで重ね、さらに暗いレイヤーを重ねます。Sが100やVが-100の端のケースは分岐して描画回数を減らしています。","つまり、ここはScratchのcolor、明るさ、透明度を組み合わせてHSVに近い操作感を作る部分です。本資料ではまずModeありの単純な1回描画を完成させ、その後にこの高度な多重描画を追加すると追いやすくなります。"],"keyPoints":["StampのModeが空欄の場合、V2は1回の標準エフェクトだけで終わらず、同じ素材を複数回スタンプします","基本色をHで描いたあと、明るいレイヤーを透明度付きで重ね、さらに暗いレイヤーを重ねます","Sが100やVが-100の端のケースは分岐して描画回数を減らしています"],"formulas":[],"en":{"title":"Building HSV-style effects with layered stamps","subtitle":"Approximate richer color control by layering the same costume.","body":["When Mode is blank, V2 can stamp the same asset several times with different brightness and transparency settings. The layers approximate an HSV-like control scheme using Scratch's built-in visual effects."],"keyPoints":["When Mode is blank, V2 can stamp the same asset several times with different brightness and transparency settings.","The layers approximate an HSV-like control scheme using Scratch's built-in visual effects."]},"lab":null,"baseLessons":["l13"]},{"id":"p13","sourcePage":13,"chapter":"drawing","tag":"第1講","title":"描画基盤の確認","subtitle":"位置・Camera・色・時間条件を一項目ずつ変えて、描画基盤を切り分けて検証する。","body":["描画基盤の確認では、複数の値を同時に変えません。まずX/Yだけを変え、画面上で正しく移動するかを確認します。次にCamera X / Zoomを変えてPositionの変換を確認し、Hueだけを変えてVFX Stampを確認します。","最後にStart / Endを変え、区間外でStampされないことを確認します。問題が起きたときに疑う定義が一つに絞れるよう、テスト条件を独立させることが重要です。"],"keyPoints":[],"formulas":[],"en":{"title":"Drawing-foundation verification","subtitle":"Verify the drawing foundation by changing position, camera, color, and time conditions one variable at a time.","body":["Do not change several subsystems at once when validating the drawing foundation. First change only X/Y and confirm movement. Then change Camera X or Zoom to verify Position, and change only Hue to verify VFX Stamp.","Finally, change Start / End and confirm that Stamp is suppressed outside the active interval. Isolating one variable at a time makes the faulty definition easy to identify."],"keyPoints":["Test one subsystem at a time.","Position problems should be separated from VFX problems.","Verify both inside and outside the Stamp time interval."]},"lab":null,"baseLessons":[]},{"id":"p14","sourcePage":14,"chapter":"time","tag":"第2講","title":"時間とEasing","subtitle":"Timerを「拍」に変換し、全アニメーションの時間軸を統一する","body":["第2講では時間管理とEasingを構成します。重要なのは、V2のTimerの単位です。V2はScratch標準の「タイマー」の秒値をそのまま使っていません。BPMを60で割って掛け、拍数へ変換しています。","つまりTimerが1なら1拍、2なら2拍です。120BPMなら1秒でTimerが2進みます。","この拍単位のTimerを基準にEasing、カメラ、Effect、Particleなどを動かすことで、音楽に合わせた指定がしやすくなっています。"],"keyPoints":["V2のTimerは秒ではなくbeat単位","BPM変更でも「1拍目・2拍目」の指定を保てる","Easingは進行度 0→1を作って任意値へ変換","Logic / SetはOrganizeから分離"],"formulas":[],"en":{"title":"Time and Easing","subtitle":"Convert Scratch seconds into beats and drive animation from one musical timeline.","body":["V2 measures its main Timer in beats rather than raw seconds. This makes camera motion, effects, particles, and other animation easier to align with music, while Easing converts beat progress into smoothly changing values."],"keyPoints":["V2 measures its main Timer in beats rather than raw seconds.","This makes camera motion, effects, particles, and other animation easier to align with music, while Easing converts beat progress into smoothly changing values."]},"lab":null,"baseLessons":["l15"]},{"id":"p15","sourcePage":15,"chapter":"time","tag":"第2講","title":"Timer Controlと拍単位Timer","subtitle":"Timer Control の先頭2項目は offset と BPM","body":["Timer Controlの1番目は開始オフセット秒、2番目はBPMです。保存されているV2では0と120が入っています。","式は、Scratchのtimerからオフセットを引き、それにBPM割る60を掛けます。120BPMならBPM割る60は2なので、実時間1秒でTimerは2、つまり2拍進みます。","Timer Controlの3番目以降には0、1、2、3という拍位置を入れています。このため、以降のt1やt2は基本的に「秒」ではなく「拍」として読む必要があります。"],"keyPoints":["Timer Controlの1番目は開始オフセット秒、2番目はBPMです","保存されているV2では0と120が入っています","式は、Scratchのtimerからオフセットを引き、それにBPM割る60を掛けます"],"formulas":["Timer = (scratchTimer - offsetSec) * (BPM / 60)","120 BPM -> 1 sec = 2 beats"],"en":{"title":"Timer Control and beat-based Timer","subtitle":"Use offset and BPM to convert Scratch timer values to beat positions.","body":["Timer Control begins with an offset in seconds and a BPM value. The engine computes (scratchTimer - offset) * BPM/60, so at 120 BPM one real second advances the engine by two beats."],"keyPoints":["Timer Control begins with an offset in seconds and a BPM value.","The engine computes (scratchTimer - offset) * BPM/60, so at 120 BPM one real second advances the engine by two beats.","Check the formulas against the live values used by the implementation."]},"lab":"timer","baseLessons":["l16"]},{"id":"p16","sourcePage":16,"chapter":"time","tag":"第2講","title":"定義 Easing","subtitle":"現在位置を0〜1へ正規化する","body":["Easingは、時刻を値へ変換する処理を三段階に分けると理解しやすくなります。最初に u=(Timer-t1)/(t2-t1) で現在時刻を0〜1へ正規化し、次にEase InやEase Outの曲線をuへ適用します。最後に value=x1+(x2-x1)×easedU として、0〜1を目的の値域へ戻します。","この構造にしておけば、座標・サイズ・回転・透明度・Cameraなど、数値で表せるほぼすべての要素を同じEasing定義で扱えます。"],"keyPoints":["Easingは、時刻を値へ変換する処理を三段階に分けると理解しやすくなります","最初に u=(Timer-t1)/(t2-t1) で現在時刻を0〜1へ正規化し、次にEase InやEase O…","最後に value=x1+(x2-x1)×easedU として、0〜1を目的の値域へ戻します"],"formulas":["u = (Timer - t1) / (t2 - t1)","value = x1 + (x2 - x1) * eased(u)"],"en":{"title":"Definition: Easing","subtitle":"Normalize the current time to a 0-1 progress value.","body":["Easing is easiest to understand as three steps: normalize time into u, reshape u with an easing curve, then map the result into the desired value range. The same pattern works for position, size, rotation, transparency, camera values, and more."],"keyPoints":["Easing is easiest to understand as three steps: normalize time into u, reshape u with an easing curve, then map the result into the desired value range.","The same pattern works for position, size, rotation, transparency, camera values, and more.","Check the formulas against the live values used by the implementation."]},"lab":"easing","baseLessons":["l17"]},{"id":"p17","sourcePage":17,"chapter":"time","tag":"第2講","title":"Ease In / Ease Out","subtitle":"V2では log と 10^ を使って u^p を作る","body":["V2のEase Inはuのp乗、Ease Outは1から1-uのp乗を引いた形です。","Scratchには一般のべき乗ブロックがないため、10のlog u×p乗、という形でuのp乗を作っています。数学的には同じ値です。","Powerが2なら二次、3なら三次のようにカーブが強くなります。イントロではOutの3や4を使うと、素早く動いて最後だけ滑らかに止まる動きが作りやすいです。"],"keyPoints":["V2のEase Inはuのp乗、Ease Outは1から1-uのp乗を引いた形です","Scratchには一般のべき乗ブロックがないため、10のlog u×p乗、という形でuのp乗を作っています","数学的には同じ値です"],"formulas":["In: eased = u^p","Out: eased = 1 - (1-u)^p","10^(log(u)*p) = u^p"],"en":{"title":"Ease In / Ease Out","subtitle":"Use powers to control how strongly motion accelerates or decelerates.","body":["Ease In uses u^p while Ease Out uses 1-(1-u)^p. V2 reproduces general powers with log and 10^ because Scratch does not provide a general exponent operator. Higher power values create stronger easing."],"keyPoints":["Ease In uses u^p while Ease Out uses 1-(1-u)^p.","V2 reproduces general powers with log and 10^ because Scratch does not provide a general exponent operator.","Higher power values create stronger easing.","Check the formulas against the live values used by the implementation."]},"lab":null,"baseLessons":["l18"]},{"id":"p18","sourcePage":18,"chapter":"time","tag":"第2講","title":"Ease InOut / Elastic","subtitle":"InOutは区間を半分に分けてEasing自身を2回呼ぶ","body":["InOutは別の長い式を持っているわけではありません。時間と値の中点を作り、前半をEase In、後半をEase OutとしてEasing自身を2回呼びます。","typeがi、o、io以外の場合は、V2ではsinを含む減衰式へ入ります。e引数を使うと振動の位相や回数を変えられる形です。Particleではpinというtype名が使われています。","本資料ではまずi、o、ioを必須として完成させ、その他のsin系は応用として最後に追加する方が分かりやすいです。"],"keyPoints":["InOutは別の長い式を持っているわけではありません","時間と値の中点を作り、前半をEase In、後半をEase OutとしてEasing自身を2回呼びます","typeがi、o、io以外の場合は、V2ではsinを含む減衰式へ入ります"],"formulas":["midT = (t1+t2)/2","midX = (x1+x2)/2","other = (1-u)^p * sin((e*u-0.75)*120) + 1"],"en":{"title":"Ease InOut / Elastic","subtitle":"Split the interval into an Ease In half and an Ease Out half.","body":["InOut can be implemented by finding the midpoint in both time and value, then calling Easing once for the first half and once for the second. V2 also contains a damped sine-style branch for additional motion types."],"keyPoints":["InOut can be implemented by finding the midpoint in both time and value, then calling Easing once for the first half and once for the second.","V2 also contains a damped sine-style branch for additional motion types.","Check the formulas against the live values used by the implementation."]},"lab":null,"baseLessons":["l19"]},{"id":"p19","sourcePage":19,"chapter":"time","tag":"第2講","title":"初期化","subtitle":"初期化は「画面・*List・Spline」の3段階","body":["Setは初期状態を整える処理です。画面を消去してpen upにし、*Listを空にした後、必要数の空スロットを確保します。SectionIndex（V2: *List 67）は3に設定します。Timer Controlの1番目は開始オフセット、2番目はBPMであり、3番目から実際の拍マーカーが始まるためです。","Splineは計算量が大きいため、Spline setを初期化時に呼び、点列を事前生成します。毎フレーム再生成しないことが軽量化の要点です。"],"keyPoints":["Setは初期状態を整える処理です","画面を消去してpen upにし、*Listを空にした後、必要数の空スロットを確保します","SectionIndex（V2: *List 67）は3に設定します"],"formulas":[],"en":{"title":"Initialization","subtitle":"Initialize the screen, shared *List storage, and precomputed spline data.","body":["Set clears the display, prepares *List slots, chooses the initial Timer Control section, and generates spline point data once. Precomputing expensive spline data here avoids repeating heavy calculations every frame."],"keyPoints":["Set clears the display, prepares *List slots, chooses the initial Timer Control section, and generates spline point data once.","Precomputing expensive spline data here avoids repeating heavy calculations every frame."]},"lab":null,"baseLessons":["l21"]},{"id":"p20","sourcePage":20,"chapter":"time","tag":"第2講","title":"メインループ","subtitle":"毎フレームのTimer区間判定をMain Logicとして独立","body":["V2のOrganizeでLogicを選んだときの中身を展開します。最初にpen clearで前フレームを消し、Timerを拍単位へ更新します。","SectionIndex（V2: *List 67）は現在のTimer Control区間を指す番号です。次のマーカーをTimerが超えたら67を1増やします。そして68へ区間開始、69へ区間終了を入れます。","その後にBG Updateとカメラを更新しています。推奨実装ではMain Logic、BG Update、カメラ Updateという名前に分けて、毎フレーム何が起きているかを見える形にします。","intro startでは、初期化して0.5秒待ち、intro musicをスタートし、タイマーをリセットしてAllを繰り返します。","V2のデータを見ると、repeat untilの条件が空欄になっています。空のBooleanはfalseとして扱われるため、そのままでは実質無限ループになり、後ろのIntro Finへ到達しません。","推奨実装ではここをそのまま真似させず、TimerがIntro Lengthを超えたら終了、という条件を明示します。完成品の圧縮や未完成箇所は、本書向けに安全な形へ直して説明します。"],"keyPoints":["V2のOrganizeでLogicを選んだときの中身を展開します","最初にpen clearで前フレームを消し、Timerを拍単位へ更新します","SectionIndex（V2: *List 67）は現在のTimer Control区間を指す番号です","V2のrepeat until条件は空欄に見え、Intro Finへ到達しない構造","推奨実装ではIntroLengthなど明示的な終了条件を入れる","sound_play opcodeは「start sound」に相当"],"formulas":[],"en":{"title":"Main loop","subtitle":"Keep per-frame time and section bookkeeping in one Main Logic routine.","body":["Main Logic clears the previous pen frame, updates beat-based Timer, advances the active Timer Control section, records its start and end markers, and then triggers background and camera updates. Separating this from rendering keeps responsibilities clear.","The original V2 loop appears effectively unbounded because its repeat-until condition is blank. A clearer implementation uses an explicit IntroLength condition so the loop can finish predictably and hand control to the ending routine."],"keyPoints":["Main Logic clears the previous pen frame, updates beat-based Timer, advances the active Timer Control section, records its start and end markers, and then triggers background and camera updates.","Separating this from rendering keeps responsibilities clear.","The original V2 loop appears effectively unbounded because its repeat-until condition is blank.","A clearer implementation uses an explicit IntroLength condition so the loop can finish predictably and hand control to the ending routine."]},"lab":null,"baseLessons":["l20","l22"]},{"id":"p21","sourcePage":21,"chapter":"camera","tag":"第3講","title":"CameraとShake","subtitle":"Camera編集値1〜4から、最終値56〜59を作る","body":["Cameraでは、編集用のCamera値と最終的なCamera値を分けます。V2では1からWorkScale（V2: 4）へX、Y、Rotation、Zoomを置き、Shakeを加えた結果をCamX / CamY / CamRotation / CamZoom（V2: 56〜59）へ書きます。","カメラの中には空欄のEasing呼び出しが1本置かれています。これはバグではなく、作者が実際のCameraアニメーションを書き込む編集スロットです。","本資料ではこの構造を見せて、カメラ本体は「演出を記述する場所」、カメラUpdateは「最終値を確定する場所」と分けます。"],"keyPoints":["1:X 2:Y 3:Rotation 4:Zoom を編集値として使う","Camera は「Easingを書くスロット」","Shakeを足して56〜59へ確定","Posは56〜59だけを見る"],"formulas":[],"en":{"title":"Camera and Shake","subtitle":"Separate editable camera values from final camera values used by Position.","body":["Each frame starts with editable X, Y, rotation, and zoom values. Camera animation writes those values, Shake modifies them, and the resulting final camera state is stored for Position to consume."],"keyPoints":["Each frame starts with editable X, Y, rotation, and zoom values.","Camera animation writes those values, Shake modifies them, and the resulting final camera state is stored for Position to consume."]},"lab":null,"baseLessons":["l23"]},{"id":"p22","sourcePage":22,"chapter":"camera","tag":"第3講","title":"定義 Camera","subtitle":"まず既定値を0,0,0,1に戻し、その区間のEasingを上書きする","body":["毎フレームCamera Updateの最初でX、Y、Rotationを0、Zoomを1へ戻します。これが基準状態です。","そのあとカメラを呼びます。ここに例えばEasing 0から100、Time 1から2、Output 1と書けば、1拍目から2拍目の間にCamera Xが0から100へ動きます。","毎フレーム既定値へ戻してから現在時刻に該当するEasingだけを適用するので、イベントを終了時に元へ戻す処理を大量に書かなくて済みます。"],"keyPoints":["毎フレームCamera Updateの最初でX、Y、Rotationを0、Zoomを1へ戻します","これが基準状態です","そのあとカメラを呼びます"],"formulas":[],"en":{"title":"Definition: Camera","subtitle":"Reset to a neutral camera every frame, then overwrite only the values active at the current time.","body":["Camera Update begins from X=0, Y=0, rotation=0, and zoom=1. Easing calls then override those defaults for the current beat, reducing the need for many manual 'restore previous value' blocks."],"keyPoints":["Camera Update begins from X=0, Y=0, rotation=0, and zoom=1.","Easing calls then override those defaults for the current beat, reducing the need for many manual 'restore previous value' blocks."]},"lab":"camera","baseLessons":["l24"]},{"id":"p23","sourcePage":23,"chapter":"camera","tag":"第3講","title":"Shake","subtitle":"現在区間の中央で5まで上げ、後半で0へ戻す","body":["Shakeでは、現在のTimer Control区間ごとに自動で揺れを作っています。68が区間開始、69が区間終了なので、その平均をShakeMid（V2: 80）へ入れて中央時刻を構成します。","前半は0から5へEase Out、後半は5から0へEase Inです。結果のShakeStrength（V2: 81）がShake strengthになります。","この方式だと、Timer Controlへ拍位置を追加するだけで、各区間に同じタイプの揺れを自動配置できます。音ハメ用の簡易Shakeとして非常に使いやすい構造です。"],"keyPoints":["Shakeでは、現在のTimer Control区間ごとに自動で揺れを作っています","68が区間開始、69が区間終了なので、その平均をShakeMid（V2:80）へ入れて中央時刻を構成します","前半は0から5へEase Out、後半は5から0へEase Inです"],"formulas":["mid = (sectionStart + sectionEnd) / 2","start -> mid : 0 to 5, Out p=3","mid -> end : 5 to 0, In p=3"],"en":{"title":"Shake","subtitle":"Raise shake intensity toward the middle of the section and return it to zero.","body":["Shake strength is treated as another time-varying value. A smooth rise-and-fall envelope avoids sudden starts and stops, and the resulting strength becomes the amplitude used by Camera Update."],"keyPoints":["Shake strength is treated as another time-varying value.","A smooth rise-and-fall envelope avoids sudden starts and stops, and the resulting strength becomes the amplitude used by Camera Update.","Check the formulas against the live values used by the implementation."]},"lab":null,"baseLessons":["l25"]},{"id":"p24","sourcePage":24,"chapter":"camera","tag":"第3講","title":"Cameraの更新順","subtitle":"ランダムではなく複数周波数のsin/cosで揺らす","body":["最終カメラはCamX / CamY / CamRotation / CamZoom（V2: 56〜59）です。ここへ通常Camera値にShakeを加えます。","Xはcos Timer×180、Yはcos Timer×270なので、同じ強度でも周期が異なります。Rotationはsinを使い、強さを4分の1に抑えます。Zoomにもstrengthの50分の1を足します。","つまりV2のShakeは乱数ではありません。複数のsinとcosを組み合わせた決定論的な揺れです。毎回同じタイミングで同じ形になるので、音ハメにも向いています。"],"keyPoints":["最終カメラはCamX / CamY / CamRotation / CamZoom（V2:56〜59）です","ここへ通常Camera値にShakeを加えます","Xはcos Timer×180、Yはcos Timer×270なので、同じ強度でも周期が異なります"],"formulas":["CamX = X + cos(Timer*180)*strength","CamY = Y + cos(Timer*270)*strength","CamRot = Rot + sin(Timer*180)*(strength/4)","Zoom = ZoomBase + strength/50"],"en":{"title":"Camera update order","subtitle":"Use deterministic sine/cosine frequencies instead of frame-by-frame random jumps.","body":["Camera Update combines the base camera with several sine/cosine oscillations scaled by Shake strength. The motion stays smooth and reproducible while still feeling irregular enough for visual impact."],"keyPoints":["Camera Update combines the base camera with several sine/cosine oscillations scaled by Shake strength.","The motion stays smooth and reproducible while still feeling irregular enough for visual impact.","Check the formulas against the live values used by the implementation."]},"lab":null,"baseLessons":["l26"]},{"id":"p25","sourcePage":25,"chapter":"camera","tag":"第3講","title":"PositionとCameraの接続","subtitle":"Camera側を作ったら、第1講のPosがそのまま全素材へ反映する","body":["Camera編で新しく素材側のコードを大量に追加する必要はありません。第1講で作ったPosがCamX / CamY / CamRotation / CamZoom（V2: 56〜59）を見るようになっているため、最終カメラ値が更新されればStampを使うすべての素材へ反映されます。","ここで動作確認として、同じStampを3か所へ置き、カメラ X、Zoom、Rotationを変えて全部が一緒に動くか確認できます。","もし1つだけ違う動きをするなら、その機能がPosを通らず直接go toしていないかを確認できます。"],"keyPoints":["Posは56〜59だけ参照する","Text/Effect/Particle側にCamera式を書かない","Camera無効時は生座標分岐を使う","Rotationは位置とdirectionの両方へ反映"],"formulas":[],"en":{"title":"Connecting Position and Camera","subtitle":"Make every Stamp-based feature inherit camera motion automatically.","body":["Once Position reads the final camera values, Text, Effect, Particle, Spline, and any future Stamp-based feature receive camera translation, rotation, and zoom without duplicating camera formulas."],"keyPoints":["Once Position reads the final camera values, Text, Effect, Particle, Spline, and any future Stamp-based feature receive camera translation, rotation, and zoom without duplicating camera formulas.","Make every Stamp-based feature inherit camera motion automatically."]},"lab":null,"baseLessons":["l27"]},{"id":"p26","sourcePage":26,"chapter":"camera","tag":"第3講","title":"Cameraの確認","subtitle":"Camera単体・Shake・Position接続を分けて確認し、更新順の破綻を防ぐ。","body":["Cameraの確認では、まずShakeを0にしてCamera X/Y/Rotation/Zoomだけを変えます。次にShakeだけを有効化し、基準Cameraへ一時的な揺れが加わることを確認します。","最後にPositionを通した描画を確認します。Text、Particle、Backgroundなど複数機能が同時にずれる場合は、個別機能ではなくCamera UpdateまたはPositionを疑います。"],"keyPoints":[],"formulas":[],"en":{"title":"Camera verification","subtitle":"Test Camera state, Shake, and the Position connection separately to prevent update-order errors.","body":["Start by setting Shake to zero and changing only Camera X/Y/Rotation/Zoom. Then enable Shake alone and verify that it offsets the base camera without permanently modifying the edit values.","Finally, render through Position. If Text, Particle, and Background all drift in the same way, inspect Camera Update or Position before debugging each feature separately."],"keyPoints":["Verify base Camera before Shake.","Shake must not permanently alter edit values.","A shared offset across many systems usually points to Camera Update or Position."]},"lab":null,"baseLessons":[]},{"id":"p27","sourcePage":27,"chapter":"text","tag":"第4講","title":"Text","subtitle":"Textは「編集値を作る部分」と「時間Blurを重ねる部分」に分ける","body":["TextはV2の中でも面白い作りです。単に同じ文字を位置だけずらしてBlurにしているのではなく、Timerそのものを少し巻き戻して過去の状態を何度も再計算しています。","Textは1回分の文字状態を決める場所、OrganizeのText部分は時間サンプリングして重ねる場所です。推奨実装では後者をDraw Textと呼びます。"],"keyPoints":["Text：位置/方向/サイズを初期化してStamp","Draw Text：Timerを巻き戻してblurを20回描く","最後にbaseを現在時刻で1回描く","clear graphic effectsで終了"],"formulas":[],"en":{"title":"Text","subtitle":"Separate single-time text state from temporal blur sampling.","body":["Text computes what one text element should look like at a specific time. Draw Text samples that definition at several nearby past times to create motion blur, then adds one sharp base pass at the current time."],"keyPoints":["Text computes what one text element should look like at a specific time.","Draw Text samples that definition at several nearby past times to create motion blur, then adds one sharp base pass at the current time."]},"lab":null,"baseLessons":["l28"]},{"id":"p28","sourcePage":28,"chapter":"text","tag":"第4講","title":"定義 Text","subtitle":"毎回0,0,90,100へ初期化し、必要ならEasingで上書き","body":["Text定義の最初では、xを0、yを0、向きを90、サイズを100へ戻します。その下に空のEasing呼び出しがあり、ここへ実際の文字アニメーションを書き込みます。","最後のStampでは、コスチュームをTextCostume（V2: 78）、明るさをTextValue（V2: 79）から受け取ります。78と79はDraw Text側でblur用とbase用に切り替えます。","つまりTextは「今この時刻なら文字はどこにいるか」を1回計算して描く定義です。Blurの回数はここでは扱いません。"],"keyPoints":["Text定義の最初では、xを0、yを0、向きを90、サイズを100へ戻します","その下に空のEasing呼び出しがあり、ここへ実際の文字アニメーションを書き込みます","最後のStampでは、コスチュームをTextCostume（V2: 78）、明るさをTextValue（V2: …"],"formulas":[],"en":{"title":"Definition: Text","subtitle":"Reset position, direction, and size, then apply animation overrides before stamping.","body":["Each Text call begins from a known neutral state and lets Easing modify selected properties. It then stamps the text costume using the current base or blur visual settings."],"keyPoints":["Each Text call begins from a known neutral state and lets Easing modify selected properties.","It then stamps the text costume using the current base or blur visual settings."]},"lab":null,"baseLessons":["l29"]},{"id":"p29","sourcePage":29,"chapter":"text","tag":"第4講","title":"時間サンプリングBlur","subtitle":"Timerを-0.1拍して、0.005拍ずつ進めながら過去状態を重ねる","body":["Draw Textでは、まずコスチュームをtext//blur、明るさを98へします。そしてTimerを0.1拍戻します。","そこから20回繰り返し、カメラをその過去時刻で再計算し、Textを描き、Timerを0.005拍進めます。20回×0.005で0.1なので、ループ終了時には元のTimerへ戻ります。","この方式なら、文字自身のEasingだけでなくカメラの過去位置も含めて残像になります。本当のモーションブラーに近い考え方です。"],"keyPoints":["Draw Textでは、まずコスチュームをtext//blur、明るさを98へします","そしてTimerを0.1拍戻します","そこから20回繰り返し、カメラをその過去時刻で再計算し、Textを描き、Timerを0.005拍進めます"],"formulas":["sampleStart = Timer - 0.100 beat","20 samples * 0.005 beat = 0.100 beat"],"en":{"title":"Temporal-sampling blur","subtitle":"Move Timer slightly into the past and draw a sequence of historical text states.","body":["Draw Text samples roughly 0.1 beat of history in 20 small steps. Each sample updates Camera and Text at that temporary time, producing a controllable motion-blur trail rather than a static blur filter."],"keyPoints":["Draw Text samples roughly 0.1 beat of history in 20 small steps.","Each sample updates Camera and Text at that temporary time, producing a controllable motion-blur trail rather than a static blur filter.","Check the formulas against the live values used by the implementation."]},"lab":null,"baseLessons":["l30"]},{"id":"p30","sourcePage":30,"chapter":"text","tag":"第4講","title":"baseで輪郭を締める","subtitle":"Blurを描き終えたら現在時刻のシャープな文字を1回追加","body":["Blurを20回描いた後、TextCostume（V2: 78）をtext//base、TextValue（V2: 79）を0へ戻します。現在時刻でカメラをもう一度計算し、Textを1回描きます。","これによって外側には時間Blurが残り、中心の輪郭だけは現在時刻のシャープな文字になります。","clear graphic effectsを入れます。TextのStampではE引数を1にして途中で効果を消さないようにしているので、Draw Textの最後でまとめてリセットする構造です。"],"keyPoints":["Blurを20回描いた後、TextCostume（V2: 78）をtext//base、TextValue（V2…","現在時刻でカメラをもう一度計算し、Textを1回描きます","これによって外側には時間Blurが残り、中心の輪郭だけは現在時刻のシャープな文字になります"],"formulas":[],"en":{"title":"Finishing the edge with a base pass","subtitle":"Restore the current time and draw one sharp text layer on top.","body":["After the blur samples, Timer returns to the actual current value and Text is stamped once with the base costume. This final pass keeps the main letterform crisp while the previous samples provide motion."],"keyPoints":["After the blur samples, Timer returns to the actual current value and Text is stamped once with the base costume.","This final pass keeps the main letterform crisp while the previous samples provide motion."]},"lab":null,"baseLessons":["l31"]},{"id":"p31","sourcePage":31,"chapter":"text","tag":"第4講","title":"TextとCamera","subtitle":"Textの座標もPositionを通し、Camera・Zoom・Rotationと同じ規則で動かす。","body":["Textだけ別のCamera式を持たせると、EffectやParticleとの位置関係が崩れやすくなります。Textの現在位置・方向・サイズを計算したあと、共通のPosition / Stampへ渡します。","時間サンプリングBlurでも各サンプル時刻ごとにCamera状態を更新してからTextを描くことで、Cameraが動いている最中も軌跡が正しくなります。"],"keyPoints":[],"formulas":[],"en":{"title":"Text and Camera","subtitle":"Route text through Position so camera translation, zoom, and rotation affect it using the same rules as other objects.","body":["Do not give Text a separate camera formula. Compute its current position, direction, and size, then pass the result through the shared Position / Stamp path used by the rest of the engine.","For temporal blur, update the Camera for each sampled time before drawing that Text sample. This keeps the blur path correct while the camera itself is moving."],"keyPoints":["Text uses the same Position path as other rendered objects.","Recompute Camera for every temporal blur sample.","Avoid duplicate camera formulas inside Text."]},"lab":null,"baseLessons":[]},{"id":"p32","sourcePage":32,"chapter":"text","tag":"第4講","title":"Textの完成例","subtitle":"Blur・Ease Out・base・Cameraを組み合わせ、文字演出を一つの流れとして確認する。","body":["完成例では、Easingで文字を移動・拡大し、過去時刻を複数回サンプリングしてBlurを重ね、最後に現在時刻のbaseを1回描きます。","Cameraを動かしても文字とBlurが同じ座標系で追従し、演出終了後にgraphic effectsが残らないことまで確認します。"],"keyPoints":[],"formulas":[],"en":{"title":"Complete Text example","subtitle":"Combine blur, easing, base rendering, and camera handling into one complete text effect.","body":["A complete Text effect eases position or size, samples several earlier times to build blur, and then draws one crisp base sample at the current time.","Move the Camera during the test and confirm that both the base and blur share the same coordinate system. Also verify that graphic effects are cleared after the effect finishes."],"keyPoints":["Blur is a stack of past-time samples.","The current-time base pass restores a crisp edge.","Camera motion and effect cleanup must be tested together."]},"lab":null,"baseLessons":[]},{"id":"p33","sourcePage":33,"chapter":"background","tag":"第5講","title":"Background","subtitle":"背景の「位置」と「必要枚数」を分け、ループ描画する","body":["Backgroundは、全体のスクロール位置を作るBG Update、必要なタイル数と相対位置を作るBG Max、1枚の背景を実際に描くBG Progressの3層に分けます。役割を分離することで、背景デザインとスクロール制御を独立して変更できます。","V2のBG Progressは編集用の枠としてほぼ空ですが、BG Updateには境界時刻で開始値が確定しない問題があります。本書ではBG Updateを区分関数に置き換え、SectionStart・BGSplit・SectionEndの全ての時刻で値が一意に定まる形を標準とします。"],"keyPoints":["BG Progress：1枚の背景の描画規則","BG Max：必要枚数とタイル位置を決定","BG Update：区間移動＋常時スクロール","修正版：開始値・境界値を常に定義"],"formulas":[],"en":{"title":"Background","subtitle":"Separate background position from the number of repeated tiles required to fill the view.","body":["The background system computes where a repeating tile strip should begin and how many tiles are necessary. This keeps scrolling and coverage logic independent, making camera-aware infinite-style backgrounds easier to manage."],"keyPoints":["The background system computes where a repeating tile strip should begin and how many tiles are necessary.","This keeps scrolling and coverage logic independent, making camera-aware infinite-style backgrounds easier to manage."]},"lab":null,"baseLessons":["l32"]},{"id":"p34","sourcePage":34,"chapter":"background","tag":"第5講","title":"定義 Background Progress","subtitle":"p＝タイル位置 / id＝背景種類 / tileIndex＝タイル番号","body":["BG Progressの引数はp、id、tileIndexです。pはそのタイルの現在位置、idは背景種類、eは何番目のタイルかを表す値として使えます。","V2ではIDが1のとき、tileIndexを2で割った余りが0かどうかまで分岐していますが、その中は空欄です。例えば偶数と奇数でコスチュームを交互に変える、向きを反転する、といった使い方ができます。","理解しやすくするためにはこの空欄を実際に1つ埋め、BG Maxから何度も呼ばれる様子を確認できます。"],"keyPoints":["BG Progressの引数はp、id、tileIndexです","pはそのタイルの現在位置、idは背景種類、eは何番目のタイルかを表す値として使えます","V2ではIDが1のとき、tileIndexを2で割った余りが0かどうかまで分岐していますが、その中は空欄です"],"formulas":[],"en":{"title":"Definition: Background Progress","subtitle":"Represent background type, tile index, and progress through a compact shared state.","body":["BG Progress prepares the current background placement values used by the tile loop. Treating progress and tile identity separately allows the same layout logic to support different background assets."],"keyPoints":["BG Progress prepares the current background placement values used by the tile loop.","Treating progress and tile identity separately allows the same layout logic to support different background assets."]},"lab":null,"baseLessons":["l33"]},{"id":"p35","sourcePage":35,"chapter":"background","tag":"第5講","title":"定義 Background Tiles","subtitle":"ProgressをSpaceの倍数へスナップし、maxまでタイル数を数える","body":["BG Maxの最初では、全体Progress 70をSpaceの倍数へ切り下げます。70から70 mod Spaceを引けば、現在位置に最も近いタイル境界が求まります。これをBGGridOrigin（V2: 74）へ入れます。","BGTileOffset（V2: 75）を0、BGTileCount（V2: 88）を0にして、maxを超えるまでSpaceずつ増やし、必要な枚数を数えます。数学的には ceil(max / space)ですが、V2ではrepeat untilで求めています。","このcountを使えば、画面外まで必要な枚数だけ背景を描けます。","必要枚数が求まったら、各タイルについてBG Progressを呼びます。pには「BGProgressと格子原点の差」にBGTileOffsetを加えた相対位置を渡し、tileIndexには基準位置から何枚離れているかをSpaceで割った値を渡します。","各反復でBGTileOffsetをSpaceだけ減らすことで、同じBG Progress定義を位置だけ変えて繰り返し利用できます。BG Progress側はpとtileIndexだけを受け取り、偶数・奇数で素材を切り替えるなど、1枚ごとの描画規則に集中できます。"],"keyPoints":["BG Maxの最初では、全体Progress 70をSpaceの倍数へ切り下げます","70から70 mod Spaceを引けば、現在位置に最も近いタイル境界が求まります","これをBGGridOrigin（V2: 74）へ入れます","必要枚数が求まったら、各タイルについてBG Progressを呼びます","pには「BGProgressと格子原点の差」にBGTileOffsetを加えた相対位置を渡し、tileIndex…","各反復でBGTileOffsetをSpaceだけ減らすことで、同じBG Progress定義を位置だけ変えて繰り…"],"formulas":["origin = 進行度 - (進行度 mod space)","count = ceil(max / space)"],"en":{"title":"Definition: Background Tiles","subtitle":"Snap the progress origin to tile spacing and count enough tiles to cover the visible range.","body":["BG Max determines how many copies are needed based on spacing and the current viewing extent. This avoids hard-coding a fixed number of tiles and reduces both gaps and unnecessary draws.","After finding the count, the engine calls BG Progress for each tile and moves the offset by one spacing unit per iteration. The result is a continuous strip constructed from a small repeated asset."],"keyPoints":["BG Max determines how many copies are needed based on spacing and the current viewing extent.","This avoids hard-coding a fixed number of tiles and reduces both gaps and unnecessary draws.","After finding the count, the engine calls BG Progress for each tile and moves the offset by one spacing unit per iteration.","The result is a continuous strip constructed from a small repeated asset."]},"lab":null,"baseLessons":["l34","l35"]},{"id":"p36","sourcePage":36,"chapter":"background","tag":"第5講","title":"Backgroundの境界処理","subtitle":"開始前・区間内・終了後の値を明示し、境界で未定義や飛びを作らない。","body":["Background Progressは区間内だけ式を計算するのではなく、開始前はStart value、終了後はEnd valueへ固定します。これにより境界時刻で値が未定義になりません。","背景のタイル枚数やスクロール位置を計算する前にProgressを必ず定義しておくと、区間切替で一瞬だけ背景が飛ぶ問題を防げます。"],"keyPoints":[],"formulas":[],"en":{"title":"Background boundary handling","subtitle":"Define values before, inside, and after each interval so boundaries never produce undefined states or jumps.","body":["Background Progress should be defined as a piecewise value: use Start value before the interval, evaluate Easing inside the interval, and hold End value afterward.","Compute tile count and scroll position only after Progress has a valid value. This prevents one-frame jumps or undefined states at section boundaries."],"keyPoints":["Before interval: Start value.","Inside interval: Easing result.","After interval: End value."]},"lab":null,"baseLessons":[]},{"id":"p37","sourcePage":37,"chapter":"background","tag":"第5講","title":"常時スクロールを合成する","subtitle":"開始・分割・終了の境界を含めて、背景位置を連続に定義","body":["V2のBG Updateには、区間の開始時刻・分割時刻・終了時刻ちょうどでBGEasedBaseが更新されない可能性があります。原因は、Easing定義が「t1 <Timer < t2」の開区間だけで出力を書き換えるのに、同じ出力先へ2本のEasingを連続して適用していることです。開始直後や境界時刻では、前フレームの値や空値が残り得ます。","修正版では、背景の基準位置を区分関数として必ず定義します。SectionStart以前はbase、前半はbase→base+250のEase Out、後半はbase+250→base+300のEase In、SectionEnd以後はbase+300とします。次の区間へ進むとbase自体が300増えるため、前区間の終値と次区間の開始値が一致し、境界で位置が飛びません。","最後に常時スクロール150×Timerを加え、BGProgressを得ます。これにより「シーン切替の移動」と「常時流れる背景」を分離したまま合成でき、開始値も常に一意に決まります。"],"keyPoints":["V2のBG Updateには、区間の開始時刻・分割時刻・終了時刻ちょうどでBGEasedBaseが更新されない可…","原因は、Easing定義が「t1 < Timer < t2」の開区間だけで出力を書き換えるのに、同じ出力先へ2本…","開始直後や境界時刻では、前フレームの値や空値が残り得ます境界を含め、すべての時刻で値を定義"],"formulas":["base = (SectionIndex - 3) × 300","split = end - 0.3(end - start)","T≤start: B=base","start<T<split: B=base + 250[1-(1-u)^3]","split≤T<end: B=base+250 + 50v^2","T≥end: B=base+300","BGProgress = B + 150T"],"en":{"title":"Adding continuous scrolling","subtitle":"Define background movement across timer sections without introducing discontinuities.","body":["BG Update combines section-specific motion with ongoing scrolling. Boundary values must agree across neighboring sections; expressing the logic as clear piecewise intervals prevents jumps when Timer crosses a marker."],"keyPoints":["BG Update combines section-specific motion with ongoing scrolling.","Boundary values must agree across neighboring sections; expressing the logic as clear piecewise intervals prevents jumps when Timer crosses a marker.","Check the formulas against the live values used by the implementation."]},"lab":null,"baseLessons":["l36"]},{"id":"p38","sourcePage":38,"chapter":"background","tag":"第5講","title":"無限スクロールとmod","subtitle":"ProgressをSpaceで折り返し、タイル位置を周期化して無限スクロールを作る。","body":["無限スクロールでは、背景全体を延々と移動させる必要はありません。Progressをタイル間隔Spaceでmodし、必要な枚数のタイルだけを繰り返し配置します。","値が負になる方向へスクロールする場合は、Scratchのmodの符号と境界を実際に確認し、0〜Spaceの範囲へ正規化してから配置すると安定します。"],"keyPoints":[],"formulas":["offset = Progress mod Space"],"en":{"title":"Infinite scrolling and mod","subtitle":"Wrap Progress by Space with mod so tile positions repeat periodically and create endless scrolling.","body":["Endless scrolling does not require an infinitely long background. Wrap Progress by tile spacing Space with mod, then draw only the number of tiles required to cover the screen.","For negative scrolling, verify Scratch’s mod behavior and normalize the wrapped offset into a stable 0-to-Space interval before placing tiles."],"keyPoints":["Wrap position, not the whole background.","Only enough tiles to cover the viewport are needed.","Check negative-value mod behavior explicitly."]},"lab":null,"baseLessons":[]},{"id":"p39","sourcePage":39,"chapter":"background","tag":"第5講","title":"BackgroundとCamera","subtitle":"ParallaxとCamera補正を分離し、背景だけに必要なCamera影響を調整する。","body":["Backgroundは通常のオブジェクトと同じCamera量で動かす必要はありません。Camera Xの一部だけを反映するParallax係数を使うと、遠景ほどゆっくり動く奥行き感を作れます。","固定背景を作る場合はCamera補正を弱めるか無効にします。背景側のCamera処理を独立した係数にしておくと、シーンごとの調整が容易です。"],"keyPoints":[],"formulas":[],"en":{"title":"Background and Camera","subtitle":"Separate parallax from camera compensation so the background can respond differently from foreground objects.","body":["A background does not have to respond to the full camera transform used by foreground objects. Multiply Camera X/Y by a parallax factor so distant layers move more slowly and create depth.","For screen-fixed backgrounds, reduce or disable camera compensation. Keeping background camera influence as an explicit factor makes scene tuning much easier."],"keyPoints":["Parallax is a controlled fraction of camera motion.","Background camera response can differ from foreground objects.","Keep the factor explicit instead of hiding it in Position."]},"lab":null,"baseLessons":[]},{"id":"p40","sourcePage":40,"chapter":"effect","tag":"第6講","title":"Effect","subtitle":"連番素材を共通ロジックで再生し、描画・配置・重ね方を分離","body":["Effectシステムでは、V2に含まれる複数系列の連番コスチュームを一つのEffect定義で再生します。コスチューム名を effects// + type + frame の規則に統一し、Timerからframeを計算することで、素材だけを差し替えて同じ再生ロジックを使えます。","V2では20 frame/beatで進むため、2拍で40フレームを再生します。Effectは「1枚をどう描くか」、Effectsは「いつ・どこへ何を出すか」、Effect Updateは「何パス重ねるか」を担当します。FlashとCoverも同じStamp基盤の上に構成されます。"],"keyPoints":["costume名 = effects// + type + frame","2拍 × 20 frame/beat = 40 frame","Effect＝描画 / Effects＝配置 / Effect Update＝重ね方","Flash・Coverも同じStamp基盤"],"formulas":[],"en":{"title":"Effect","subtitle":"Play numbered costume sequences with shared timing and rendering logic.","body":["Effects are built from frame sequences rather than separate custom engines. The Effect definition chooses the current frame, while Effect Update and Effects decide how many layers to draw and where authored effect events appear."],"keyPoints":["Effects are built from frame sequences rather than separate custom engines.","The Effect definition chooses the current frame, while Effect Update and Effects decide how many layers to draw and where authored effect events appear."]},"lab":null,"baseLessons":["l37"]},{"id":"p41","sourcePage":41,"chapter":"effect","tag":"第6講","title":"9系列のエフェクト素材","subtitle":"sw / da / hw / qsw / gsw / gda / ghw / fw / cfw","body":["ここではV2に実際に入っている9系列を示します。sw、da、hw、qsw、gsw、gda、ghw、fw、cfwで、それぞれ40フレーム、合計360枚です。","重要なのは形そのものより命名規則です。Effectではtype文字列に現在フレーム番号をjoinするので、prefixが揃っていれば新しい素材系列も同じコードで扱えます。","素材を生成するときも、全フレームでキャンバスサイズ、中心、余白を固定しておく必要があります。"],"keyPoints":["9系列それぞれ40枚、合計360枚","同じprefix+番号規則なのでEffectから動的に選べる","中央・余白・回転中心が揃った素材ほど再利用しやすい"],"formulas":[],"en":{"title":"Nine effect-asset families","subtitle":"Understand the sw / da / hw / qsw / gsw / gda / ghw / fw / cfw asset families.","body":["V2 groups effect frames by naming convention. Treating each prefix as one visual family makes frame lookup, authoring, and replacement more predictable than relying on raw costume indices."],"keyPoints":["V2 groups effect frames by naming convention.","Treating each prefix as one visual family makes frame lookup, authoring, and replacement more predictable than relying on raw costume indices."]},"lab":null,"baseLessons":["l38"]},{"id":"p42","sourcePage":42,"chapter":"effect","tag":"第6講","title":"定義 Effect","subtitle":"開始tから2拍だけ描き、現在フレームを1〜40へ変換","body":["Effectのフレーム番号は、Timerから開始時刻tを引き、それに20を掛けて切り上げます。開始直後が1、2拍後が40です。","StampのT引数にもtとt+2を入れているので、2拍を過ぎると描画自体が止まります。","120BPMなら2拍は1秒なので実時間では約40fps相当になりますが、BPMを変えると実時間fpsも変わります。V2は秒ではなく拍へ演出長を固定する設計だということをここでも確認できます。","Effectの最初では、EffectPass（V2: 64）を見て明るさ用のEffectValue（V2: 55）を決めます。64が空欄なら入力Vを使い、空欄でなければ90にします。EffectPass（V2:64）は後で説明する二重レイヤーの判定です。","EffectDirection（V2: 54）には最初のdirectionを入れます。","repeat回数は少し変わった式で、fwが空欄なら1回、数値ならその数だけ繰り返します。fwを4にすれば90度ずつ回した4枚を出す、といった放射配置ができます。","Effectの描画は、EffectPass（V2: 64）によって本体レイヤーと補助レイヤーを切り替えます。補助レイヤーではxを+10、yを-10ずらし、彩度や明るさも別値にして、影・縁取り・発光のような二重表現を構成します。本体レイヤーでは入力された位置・S・Vをそのまま使用します。","同じEffect呼び出しを複数パスで再利用するため、素材ごとに別コードを持たずに見た目の厚みを追加できます。"],"keyPoints":["Effectのフレーム番号は、Timerから開始時刻tを引き、それに20を掛けて切り上げます","開始直後が1、2拍後が40です","StampのT引数にもtとt+2を入れているので、2拍を過ぎると描画自体が止まります","Effectの最初では、EffectPass（V2: 64）を見て明るさ用のEffectValue（V2: 55…","64が空欄なら入力Vを使い、空欄でなければ90にします","EffectPass（V2: 64）は後で説明する二重レイヤーの判定です","Effectの描画は、EffectPass（V2: 64）によって本体レイヤーと補助レイヤーを切り替えます","補助レイヤーではxを+10、yを-10ずらし、彩度や明るさも別値にして、影・縁取り・発光のような二重表現を構成します","本体レイヤーでは入力された位置・S・Vをそのまま使用します"],"formulas":["frame = ceil((Timer - t) * 20)","2 beat * 20 frame/beat = 40 frames"],"en":{"title":"Definition: Effect","subtitle":"Map elapsed beat time into frames 1-40 and draw only during the effect window.","body":["Effect converts the time since its start into a costume-frame index and ignores calls outside the configured lifetime. This turns a numbered costume sequence into a reusable time-based animation.","The first half of Effect computes the visual parameters shared by all passes of the current frame. Keeping setup separate from actual stamping makes multi-layer effects easier to reason about.","Each pass can adjust position, saturation, brightness, or other parameters before calling the common Stamp pipeline. The asset animation stays separate from the generic rendering system."],"keyPoints":["Effect converts the time since its start into a costume-frame index and ignores calls outside the configured lifetime.","This turns a numbered costume sequence into a reusable time-based animation.","The first half of Effect computes the visual parameters shared by all passes of the current frame.","Keeping setup separate from actual stamping makes multi-layer effects easier to reason about."]},"lab":"stamp","baseLessons":["l39","l40","l41"]},{"id":"p43","sourcePage":43,"chapter":"effect","tag":"第6講","title":"Effectの二重描画","subtitle":"64=1の補助レイヤー → 64空欄の本体レイヤー","body":["Effect Updateは描画パスを管理します。最初にEffectPass=1として補助レイヤーを描き、次にEffectPassを空欄へ戻して本体レイヤーを描きます。Effects定義に書かれた演出内容は同じまま、EffectPassだけで見た目を切り替える構造です。","この分離により、Effectsは「いつ・どのEffectを出すか」、Effectは「1枚をどう描くか」、Effect Updateは「何パス描くか」という責務になります。"],"keyPoints":["Effect Updateは描画パスを管理します","最初にEffectPass=1として補助レイヤーを描き、次にEffectPassを空欄へ戻して本体レイヤーを描きます","Effects定義に書かれた演出内容は同じまま、EffectPassだけで見た目を切り替える構造です"],"formulas":[],"en":{"title":"Double-pass Effect rendering","subtitle":"Draw an auxiliary pass first, then the main pass.","body":["V2 uses a shared pass flag to render a supporting layer and then the primary layer. Centralizing this two-pass policy avoids duplicating the same sequencing in every authored effect event."],"keyPoints":["V2 uses a shared pass flag to render a supporting layer and then the primary layer.","Centralizing this two-pass policy avoids duplicating the same sequencing in every authored effect event."]},"lab":null,"baseLessons":["l42"]},{"id":"p44","sourcePage":44,"chapter":"effect","tag":"第6講","title":"定義 Effects","subtitle":"V2では空定義。Effect呼び出しを作者が並べる編集スロット","body":["EffectsはV2では空です。これはEffectエンジンが未完成という意味ではなく、実際のイントロごとのエフェクト配置を書くためのスロットです。","ここへEffect swを2拍目、fwを3拍目、といった呼び出しを並べます。Effect UpdateがEffectsを二重レイヤーで2回実行してくれます。","理解しやすくするためには最低2種類を実際に配置し、typeだけ変えて同じ定義から別の連番素材が再生されることを確認できます。"],"keyPoints":["EffectsはV2では空です","これはEffectエンジンが未完成という意味ではなく、実際のイントロごとのエフェクト配置を書くためのスロットです","ここへEffect swを2拍目、fwを3拍目、といった呼び出しを並べます"],"formulas":[],"en":{"title":"Definition: Effects","subtitle":"Keep authored Effect calls in a dedicated definition.","body":["The Effects definition is intentionally an editing surface rather than a large engine. The creator places timed Effect calls here, while the reusable Effect logic remains unchanged."],"keyPoints":["The Effects definition is intentionally an editing surface rather than a large engine.","The creator places timed Effect calls here, while the reusable Effect logic remains unchanged."]},"lab":null,"baseLessons":["l43"]},{"id":"p45","sourcePage":45,"chapter":"effect","tag":"第6講","title":"FlashとCover","subtitle":"各区間で明るさ 70→100をEase Out","body":["FlashではTimer Controlの3番目から最後まで、各区間を順番に走査します。FlashValue（V2: 77）を100へ初期化し、区間開始から次の区間まで明るさを70から100へEase Outさせます。","その値をSiz hackの全画面Stampへ渡します。つまり音の区切りごとに画面全体の明るいレイヤーを重ねる構造です。","本資料では、まず単純な白い全画面コスチュームで透明度をEasingするFlashを作り、その後V2の明るさ方式を紹介すると理解しやすくなります。","Coverでは最初にOverlayを画面へ置き、その上でFlashを呼びます。その後、CoverコスチュームのサイズをEasingで変えて場面を覆います。","V2のコードには-5拍から-2拍という負の時間が入っています。現在のintro startではTimerを音開始時にresetするので、このpre-rollはそのままだと動きにくい部分です。","推奨実装では負の時刻をそのまま真似させず、LeadInを明示するか0拍以降へ移して、場面転換の原理に集中します。"],"keyPoints":["FlashではTimer Controlの3番目から最後まで、各区間を順番に走査します","FlashValue（V2: 77）を100へ初期化し、区間開始から次の区間まで明るさを70から100へEase…","その値をSiz hackの全画面Stampへ渡します","V2では負の拍時刻を使うpre-roll設計が残っている","推奨実装ではLeadIn変数か0拍以降へ置き換えると分かりやすい","CoverはAllの最後に描いて最前面へ"],"formulas":[],"en":{"title":"Flash and Cover","subtitle":"Use an Ease Out brightness ramp for each section boundary.","body":["Flash iterates through Timer Control sections and computes a brightness envelope for a full-screen stamp. It is a specialized use of the same Timer, Easing, and Stamp building blocks.","Cover places full-screen transition assets at the front of the composition. V2 contains negative beat timings that are difficult to reconcile with a timer reset at audio start, so a cleaner implementation uses an explicit lead-in or non-negative timing."],"keyPoints":["Flash iterates through Timer Control sections and computes a brightness envelope for a full-screen stamp.","It is a specialized use of the same Timer, Easing, and Stamp building blocks.","Cover places full-screen transition assets at the front of the composition.","V2 contains negative beat timings that are difficult to reconcile with a timer reset at audio start, so a cleaner implementation uses an explicit lead-in or non-negative timing."]},"lab":null,"baseLessons":["l44","l45"]},{"id":"p46","sourcePage":46,"chapter":"effect","tag":"第6講","title":"エフェクトSVGの幾何","subtitle":"後でそのまま画像生成へ渡せる素材仕様","body":["エフェクト素材をAIで作る場合、見た目の指示より先に技術条件を固定します。透過背景、正方形、中心固定、全フレーム同じ余白が必須です。","色は白からグレー主体にすると、Scratch側のcolorや明るさで色を変えやすくなります。フレームごとに中心がずれるとEffect再生時に震えて見えるので、center and scale must stay consistentと明示します。","最終的な画像生成用プロンプトは、エフェクト編の素材仕様に合わせて別紙として作れる形にしてあります。"],"keyPoints":["透過背景・正方形・中心固定","全フレーム同じcanvas/viewBox/余白","白〜グレー主体：Scratch側で色変更しやすくする","輪郭がフレーム外へ切れない"],"formulas":[],"en":{"title":"Geometry for effect SVGs","subtitle":"Fix technical frame constraints before asking an image model for visual style.","body":["Sequence assets should use transparent square canvases, a stable center, consistent margins, and consistent scale across every frame. White-to-gray artwork is easier to recolor later with Scratch visual effects."],"keyPoints":["Sequence assets should use transparent square canvases, a stable center, consistent margins, and consistent scale across every frame.","White-to-gray artwork is easier to recolor later with Scratch visual effects."]},"lab":null,"baseLessons":["l46"]},{"id":"p47","sourcePage":47,"chapter":"effect","tag":"第6講","title":"エフェクトSVG一括生成 完全版プロンプト 1/6","subtitle":"SVG素材を一括生成するための完全プロンプト 1/6。役割・出力形式・全体制約。","body":["このページから6ページに分けて、エフェクトSVGを大量生成するときの完全プロンプトを掲載します。最初に、生成器の役割、透過背景、正方形キャンバス、中央配置、編集しやすい白〜グレー主体など、全系列に共通する条件を固定します。"],"keyPoints":[],"formulas":[],"en":{"title":"Complete batch SVG prompt 1/6","subtitle":"Complete SVG batch-generation prompt, part 1 of 6: role, output contract, and global constraints.","body":["This begins the six-part master prompt for generating many effect SVG assets consistently. Define the generator role, transparent background, square canvas, centered geometry, and mostly white-to-gray artwork so color can be adjusted later inside Scratch."],"keyPoints":["Lock global constraints before describing individual effects.","Use transparent square SVGs with consistent centering.","Prefer neutral values that can be recolored later."]},"lab":null,"baseLessons":[]},{"id":"p48","sourcePage":48,"chapter":"effect","tag":"第6講","title":"エフェクトSVG一括生成 完全版プロンプト 2/6","subtitle":"完全プロンプト 2/6。連番フレームとアニメーション整合性。","body":["各系列は同じ命名規則とフレーム数で出力し、回転中心・余白・線幅の基準を揃えます。連番で再生したときに中心が揺れたりサイズが跳ねたりしないよう、全フレームの座標系を固定します。"],"keyPoints":[],"formulas":[],"en":{"title":"Complete batch SVG prompt 2/6","subtitle":"Complete SVG batch-generation prompt, part 2 of 6: frame sequencing and animation consistency.","body":["For each effect family, enforce one naming rule and a consistent frame count. Keep the pivot, margins, stroke-weight policy, and coordinate system fixed across every frame so sequence playback does not jitter or change scale unexpectedly."],"keyPoints":["Stable pivot and margins prevent visible jitter.","Frame naming must be machine-sortable.","Animation continuity matters more than isolated-frame detail."]},"lab":null,"baseLessons":[]},{"id":"p49","sourcePage":49,"chapter":"effect","tag":"第6講","title":"エフェクトSVG一括生成 完全版プロンプト 3/6","subtitle":"完全プロンプト 3/6。SVG幾何・パス設計の規則。","body":["SVGは可能な限り基本図形と明確なpathで構成し、過剰なフィルタや埋め込み画像を避けます。中央基準・対称性・余白を数値で守り、Scratchへ読み込んだ後も回転中心を合わせやすくします。"],"keyPoints":[],"formulas":[],"en":{"title":"Complete batch SVG prompt 3/6","subtitle":"Complete SVG batch-generation prompt, part 3 of 6: geometric construction rules.","body":["Construct SVGs from clean vector primitives and explicit paths. Avoid raster images and unnecessarily expensive filters. Preserve numeric centering, symmetry, and safe margins so the costume pivot remains predictable after import into Scratch."],"keyPoints":["Keep geometry genuinely vector-based.","Avoid unnecessary filters and embedded raster data.","Centering and safe margins must be measurable, not approximate."]},"lab":null,"baseLessons":[]},{"id":"p50","sourcePage":50,"chapter":"effect","tag":"第6講","title":"エフェクトSVG一括生成 完全版プロンプト 4/6","subtitle":"完全プロンプト 4/6。9系列の素材と命名規則。","body":["Ring、line、shockwave、glowなど複数系列を同じ出力規約で作り、effects//系列名+連番のような一貫した命名にします。系列ごとに「何が時間とともに変わるか」を一つに絞ると、フレーム間の意図が明確になります。"],"keyPoints":[],"formulas":[],"en":{"title":"Complete batch SVG prompt 4/6","subtitle":"Complete SVG batch-generation prompt, part 4 of 6: the nine effect families and naming scheme.","body":["Generate all effect families under one output contract, using a predictable name such as effects//familyNN. For each family, define the primary changing property - radius, thickness, opacity, split distance, or another single visual progression - so the sequence has a clear temporal intent."],"keyPoints":["One naming scheme should cover every family.","Give each sequence one primary animation variable.","Keep unrelated styling changes out of the frame progression."]},"lab":null,"baseLessons":[]},{"id":"p51","sourcePage":51,"chapter":"effect","tag":"第6講","title":"エフェクトSVG一括生成 完全版プロンプト 5/6","subtitle":"完全プロンプト 5/6。manifest・ZIP・検証用情報。","body":["大量生成ではSVG本体だけでなく、系列名・フレーム番号・ファイル名を対応づけるmanifestを出力します。ZIP化するときも階層や命名を崩さず、再生成した一部だけを差し替えられる構成にします。"],"keyPoints":[],"formulas":[],"en":{"title":"Complete batch SVG prompt 5/6","subtitle":"Complete SVG batch-generation prompt, part 5 of 6: manifest and packaging requirements.","body":["A batch generator should output a manifest that maps family names, frame indices, and filenames in addition to the SVG files themselves. Packaging must preserve deterministic names so a subset can be regenerated and replaced without rebuilding the entire asset library."],"keyPoints":["Generate metadata together with assets.","Deterministic names make partial regeneration safe.","Packaging must preserve the same file order and family structure."]},"lab":null,"baseLessons":[]},{"id":"p52","sourcePage":52,"chapter":"effect","tag":"第6講","title":"エフェクトSVG一括生成 完全版プロンプト 6/6","subtitle":"完全プロンプト 6/6。最終品質検査と再生成条件。","body":["最後に、透過背景、viewBox、中央位置、余白、連番の連続性、命名、破損パスの有無を機械的に確認します。条件を満たさないSVGはそのまま納品せず、該当フレームだけ再生成するよう指示します。"],"keyPoints":[],"formulas":[],"en":{"title":"Complete batch SVG prompt 6/6","subtitle":"Complete SVG batch-generation prompt, part 6 of 6: final QA and rejection criteria.","body":["Finish with mechanical validation: transparent background, valid viewBox, centered artwork, safe margins, frame continuity, deterministic naming, and valid vector paths. Reject and regenerate only the failing frames rather than accepting a partially broken sequence."],"keyPoints":["Validate every SVG before packaging.","Reject broken frames instead of silently keeping them.","QA rules belong inside the generation prompt, not as an afterthought."]},"lab":null,"baseLessons":[]},{"id":"p53","sourcePage":53,"chapter":"particle","tag":"第7講","title":"Particle","subtitle":"クローン状態を保存せず「この時刻ならどこにいるか」を再計算","body":["Particleは、クローンを大量に保存する方式ではなく、現在時刻から生存中の粒子だけを再構成する方式で扱います。各粒子は整数のparticleIndexを持ち、birth =particleIndex×Paceで発生時刻を復元します。","乱数はフレームごとに新しく引くのではなく、particleIndexから決定論的に生成します。同じindexは必ず同じ角度を返すため、状態を保存しなくても粒子がワープしません。本書ではV2のRandを、sin・sqrt・abs・modだけで構成できる1本の式へ置き換えます。"],"keyPoints":["粒子は保存せず、時刻から状態を再構成","整数particleIndexをseedにする","1本の疑似乱数式で0〜1を生成","寿命外の粒子は描画しない"],"formulas":[],"en":{"title":"Particle","subtitle":"Reconstruct particles from time instead of storing clone state.","body":["Each particle is identified by an integer index. Birth time and deterministic random values are recomputed from that index, so the engine only draws particles that should be alive at the current time and never needs to persist every particle object."],"keyPoints":["Each particle is identified by an integer index.","Birth time and deterministic random values are recomputed from that index, so the engine only draws particles that should be alive at the current time and never needs to persist every particle object."]},"lab":null,"baseLessons":["l47"]},{"id":"p54","sourcePage":54,"chapter":"particle","tag":"第7講","title":"疑似乱数","subtitle":"整数particleIndexをseedに、同じ値を再現できる0〜1ハッシュへ置換","body":["V2のRandは大きな整数の乗算と剰余を複数回行いますが、Particle用途では値の偏りや扱いづらさが残ります。本資料では、同じseedから毎回同じ0以上1未満の値を1本の式で返す決定論的ハッシュへ置き換えます。","推奨式は R(s) = abs(sin(123.456s + 78.233√(|s|+1)) × 43758.5453) mod 1 です。Scratchのsinは度数法なので、そのまま演算ブロックへ写せます。absを入れてからmod 1を取るため、出力範囲は常に0以上1未満です。暗号学的乱数ではありませんが、視覚エフェクト用の疑似乱数として十分に散らばり、同じseedなら必ず同じ値になります。","同じ粒子から角度・サイズ・色など複数の値が必要な場合は、seedにsaltを加えます。例えばR(seed)、R(seed+97.31)、R(seed+194.62)のように入力だけずらせば、同じ1本の式から別系列を得られます。"],"keyPoints":["V2のRandは大きな整数の乗算と剰余を複数回行いますが、Particle用途では値の偏りや扱いづらさが残ります","本資料では、同じseedから毎回同じ0以上1未満の値を1本の式で返す決定論的ハッシュへ置き換えます","推奨式は R(s) = abs(sin(123.456s + 78.233√(|s|+1)) ×43758.5…"],"formulas":["R(s) = abs(sin(123.456s + 78.233√(|s|+1)) × 43758.5453) mod 1"],"en":{"title":"Deterministic pseudo-randomness","subtitle":"Generate a reproducible 0-1 value from an integer particle seed.","body":["The recommended visual hash combines sin, sqrt, abs, and mod. The same seed always produces the same value, and adding a salt creates independent-looking streams for angle, size, color, and other attributes."],"keyPoints":["The recommended visual hash combines sin, sqrt, abs, and mod.","The same seed always produces the same value, and adding a salt creates independent-looking streams for angle, size, color, and other attributes.","Check the formulas against the live values used by the implementation."]},"lab":null,"baseLessons":["l48"]},{"id":"p55","sourcePage":55,"chapter":"particle","tag":"第7講","title":"1つのseedから複数の乱数","subtitle":"同じparticle indexにsaltを加え、角度・サイズ・色で別系列の決定論的乱数を作る。","body":["1つの粒子から複数の疑似乱数が必要な場合、別の乱数器を作る必要はありません。同じR(s)へ異なるsaltを加えたseedを渡します。","例えばR(seed)、R(seed+97.31)、R(seed+194.62)を角度・サイズ・色に割り当てれば、同じ粒子では毎フレーム同じ値を再現しながら、各用途の系列を分離できます。"],"keyPoints":[],"formulas":["R1 = R(seed)","R2 = R(seed + 97.31)","R3 = R(seed + 194.62)"],"en":{"title":"Multiple random channels from one seed","subtitle":"Add different salts to the same particle index to derive independent deterministic values for angle, size, color, and more.","body":["You do not need several random generators to give one particle several stable random properties. Reuse the same deterministic R(s) function and add a different salt to the seed for each property.","For example, use R(seed), R(seed + 97.31), and R(seed + 194.62) for angle, size, and color. Each particle remains repeatable every frame while the properties use decorrelated sequences."],"keyPoints":["One deterministic function can produce many random-looking channels.","Change the salt, not the generator.","The same particle index must reproduce the same values every frame."]},"lab":null,"baseLessons":[]},{"id":"p56","sourcePage":56,"chapter":"particle","tag":"第7講","title":"定義 Particle","subtitle":"整数particleIndexからbirthを再構成し、寿命内だけ描画","body":["Particleは、粒子をクローンとして保存するのではなく、現在時刻から「今生きている粒子番号」を逆算して描画します。浮動小数の発生時刻そのものをseedにするより、整数のparticleIndexを基準にした方が再現性と可読性が高くなります。","最初の候補を firstIndex = floor((Timer-Length)/Pace)+1、最後の候補を lastIndex= floor(Timer/Pace) とします。各整数nについて birth = n×Pace、age = Timer-birth を計算し、0≦age<Lengthの粒子だけを描画します。これなら現在時刻ちょうどに生まれる粒子も取りこぼしません。","疑似乱数のseedには n + ID×1000 を使います。Paceが小数でもseed自体は整数を基準にでき、同じ粒子がフレームごとに別方向へ跳ぶ問題を防げます。"],"keyPoints":["Particleは、粒子をクローンとして保存するのではなく、現在時刻から「今生きている粒子番号」を逆算して描画します","浮動小数の発生時刻そのものをseedにするより、整数のparticleIndexを基準にした方が再現性と可読性が…","最初の候補を firstIndex = floor((Timer-Length)/Pace)+1、最後の候補を …"],"formulas":["firstIndex = floor((Timer-Length)/Pace) + 1","lastIndex = floor(Timer/Pace)","birth = n × Pace, age = Timer - birth"],"en":{"title":"Definition: Particle","subtitle":"Compute the integer index range that can satisfy 0 <= age < lifetime.","body":["Rather than loop over every particle ever created, the engine derives firstIndex and lastIndex from Timer, Pace, and Length. Each candidate reconstructs its birth time and is drawn only if it is currently within its lifetime."],"keyPoints":["Rather than loop over every particle ever created, the engine derives firstIndex and lastIndex from Timer, Pace, and Length.","Each candidate reconstructs its birth time and is drawn only if it is currently within its lifetime.","Check the formulas against the live values used by the implementation."]},"lab":"particle","baseLessons":["l49"]},{"id":"p57","sourcePage":57,"chapter":"particle","tag":"第7講","title":"半径と角度","subtitle":"Easingで半径0→300、Randから角度を固定","body":["ID=1の粒子は、寿命内の進行度u=age/Lengthから半径を決め、中心から放射状に移動させます。半径はEasingを通して0→300へ変化させ、角度はangle = 360×R(seed)で固定します。座標はx=cos(angle)×radius、y=sin(angle)×radiusです。","V2と同様に1つのseedから2枚描く場合は、2枚目の角度へ135度を加えます。向きとサイズを半径へ連動させるなら、direction=0.35×radius、size=70+0.1×radiusとできます。必要であればsalt付きR(seed+97.31)を使い、サイズや色へ独立した揺らぎを追加できます。"],"keyPoints":["ID=1の粒子は、寿命内の進行度u=age/Lengthから半径を決め、中心から放射状に移動させます","半径はEasingを通して0→300へ変化させ、角度はangle =360×R(seed)で固定します","座標はx=cos(angle)×radius、y=sin(angle)×radiusです"],"formulas":["u = age / Length","radius = Ease(0→300, u)","seed = n + ID×1000","angle = 360×R(seed)","(x,y) = radius(cos angle, sin angle)"],"en":{"title":"Radius and angle","subtitle":"Use eased age for radius and a deterministic random angle for radial motion.","body":["A particle's normalized age drives an easing from radius 0 to 300. Its index-derived seed fixes the angle, and x/y are obtained from cosine and sine, producing stable outward trajectories without saved state."],"keyPoints":["A particle's normalized age drives an easing from radius 0 to 300.","Its index-derived seed fixes the angle, and x/y are obtained from cosine and sine, producing stable outward trajectories without saved state.","Check the formulas against the live values used by the implementation."]},"lab":null,"baseLessons":["l50"]},{"id":"p58","sourcePage":58,"chapter":"particle","tag":"第7講","title":"DirectionとSize","subtitle":"距離が伸びるほどdirectionとsizeを変化","body":["粒子の位置だけでなく、向き・大きさ・色などを同じ寿命進行度から派生させると、演出全体に一貫性が出ます。V2ではdirection=0.35×radius、size=70+0.1×radiusとして、中心から離れるほど向きとサイズを変化させています。","一方、すべてをradiusだけに依存させると粒子が均一になりやすいため、必要に応じて疑似乱数のsaltを使います。例えばsize=(60+0.12×radius)×(0.85+0.3×R(seed+97.31))とすれば、軌道の連続性を保ちながら粒子ごとの個体差を付けられます。"],"keyPoints":["粒子の位置だけでなく、向き・大きさ・色などを同じ寿命進行度から派生させると、演出全体に一貫性が出ます","V2ではdirection=0.35×radius、size=70+0.1×radiusとして、中心から離れるほ…","一方、すべてをradiusだけに依存させると粒子が均一になりやすいため、必要に応じて疑似乱数のsaltを使います"],"formulas":["direction = radius * 0.35","size = 70 + radius * 0.1"],"en":{"title":"Direction and Size","subtitle":"Keep related visual properties coherent while allowing salted variation.","body":["Direction and size can be functions of the same radius used for position, so the whole particle evolves consistently. Optional salted random values add per-particle individuality without changing its deterministic trajectory."],"keyPoints":["Direction and size can be functions of the same radius used for position, so the whole particle evolves consistently.","Optional salted random values add per-particle individuality without changing its deterministic trajectory.","Check the formulas against the live values used by the implementation."]},"lab":null,"baseLessons":["l51"]},{"id":"p59","sourcePage":59,"chapter":"particle","tag":"第7講","title":"Particleの負荷管理","subtitle":"現在生存し得るindexだけを列挙し、保存する粒子状態と毎フレームの計算量を減らす。","body":["負荷を抑える鍵は、全粒子をクローンとして保持しないことです。Timer、Pace、Lengthから現在生存し得る最初と最後のparticle indexを逆算し、その範囲だけを描画します。","Paceを小さくすると同時生存数はおおよそLength / Paceに比例して増えます。見た目を調整するときは、粒子数・Stamp回数・Blurや多重描画を同時に増やしすぎないようにします。"],"keyPoints":[],"formulas":["aliveCount ≈ Length / Pace"],"en":{"title":"Particle performance management","subtitle":"Enumerate only particle indices that can still be alive, minimizing stored state and per-frame work.","body":["The main performance rule is to avoid storing every particle as a clone. Derive the first and last particle indices that can still be alive from Timer, Pace, and Length, then iterate only that range.","Reducing Pace increases concurrent particles roughly in proportion to Length / Pace. When tuning visuals, do not simultaneously multiply particle count, stamps per particle, blur samples, and layered drawing passes."],"keyPoints":["Iterate only currently possible live indices.","Concurrent count is roughly Length / Pace.","Budget particle count and stamps together."]},"lab":null,"baseLessons":[]},{"id":"p60","sourcePage":60,"chapter":"spline","tag":"第8講","title":"Spline","subtitle":"制御点 → 400補間点 → Pen/Stampで描画するSpline","body":["最後はSplineです。V2の中で最も数式と依存が多い部分なので、生成と描画を完全に分けて説明します。","Ippへ制御点を入れ、Spline setが1本分ずつIpp cacheへ切り出します。Spline Generateが400点を計算し、xとyを交互にSpline posへ保存します。","毎フレームのSpline定義では、その事前生成済み点列の一部だけをPenでなぞります。"],"keyPoints":["Ipp：制御点入力","Ipp cache：1本分だけ切り出す","Spline Generate：1本につき400点を作る","Spline pos：x,yを交互に800項目保存"],"formulas":[],"en":{"title":"Spline","subtitle":"Convert control points into precomputed samples, then draw only the required portion each frame.","body":["Spline has two phases: Spline set / Generate creates a dense x-y sample list, and the per-frame Spline routine renders a moving window of those samples with Pen and Stamp. Separating these phases is critical for performance."],"keyPoints":["Spline has two phases: Spline set / Generate creates a dense x-y sample list, and the per-frame Spline routine renders a moving window of those samples with Pen and Stamp.","Separating these phases is critical for performance."]},"lab":null,"baseLessons":["l52"]},{"id":"p61","sourcePage":61,"chapter":"spline","tag":"第8講","title":"Splineの3つのリスト","subtitle":"x,y,x,y,... を並べ、カンマ「,」でSplineを区切る","body":["IppはSplineの元になる制御点リストです。x、y、x、yと交互に座標を並べ、1本のSplineが終わったら文字のカンマを区切りとして入れます。","Spline setはIppを先頭から読み、カンマまでの項目だけIpp cacheへコピーします。その1本分をSpline Generateへ渡し、終わったら次のカンマまで進みます。","本資料では最初に4点だけのSplineを1本作り、Ippの中身を画面に表示しながら確認できます。"],"keyPoints":["Spline setは「,」までをIpp cacheへコピー","1本のSplineはx,yのペア列","Ipp cacheの長さは偶数になるようにする"],"formulas":[],"en":{"title":"The three Spline lists","subtitle":"Store x,y pairs and separate multiple splines with comma markers.","body":["Ipp is a compact serialized control-point list. Spline set copies one comma-delimited group into Ipp cache, generates that spline, and then continues to the next group."],"keyPoints":["Ipp is a compact serialized control-point list.","Spline set copies one comma-delimited group into Ipp cache, generates that spline, and then continues to the next group."]},"lab":null,"baseLessons":["l53"]},{"id":"p62","sourcePage":62,"chapter":"spline","tag":"第8講","title":"定義 Spline Set","subtitle":"Ippをカンマ区切りで1本ずつcacheへ切り出す","body":["Spline setでは最初にSpline posを空にし、IppCursor（V2: 115）を0へします。外側のrepeat untilでIpp全体を走査します。","各Splineの開始時にIpp cacheを空にし、115を1進めます。そこからカンマが出るまでIppの項目をcacheへコピーします。カンマへ到達したらSpline Generateを1回呼びます。","この構造により、複数Splineを1つのIppリストへ連続して保存できます。"],"keyPoints":["Spline setでは最初にSpline posを空にし、IppCursor（V2:115）を0へします","外側のrepeat untilでIpp全体を走査します","各Splineの開始時にIpp cacheを空にし、115を1進めます"],"formulas":[],"en":{"title":"Definition: Spline Set","subtitle":"Split Ipp into one cached spline at a time and generate each one once.","body":["Spline set clears the output list, scans Ipp with a cursor, copies values until the next comma, and calls Spline Generate. This supports multiple independent splines in one source list."],"keyPoints":["Spline set clears the output list, scans Ipp with a cursor, copies values until the next comma, and calls Spline Generate.","This supports multiple independent splines in one source list."]},"lab":null,"baseLessons":["l54"]},{"id":"p63","sourcePage":63,"chapter":"spline","tag":"第8講","title":"n次ベジェ曲線の一般式","subtitle":"n次ベジェ曲線をBernstein基底で表し、制御点から曲線上の点を計算する。","body":["n次ベジェ曲線は、制御点P0〜PnをBernstein基底で重み付けして足し合わせます。t=0ではP0、t=1ではPnを通り、中間では各制御点の影響が滑らかに変化します。","Scratchへそのまま一般式を実装すると組合せ計算が大きくなるため、実装ではde Casteljau法へ置き換えると構造を単純化できます。"],"keyPoints":[],"formulas":["B(t) = Σ C(n,i)(1-t)^(n-i)t^i P_i"],"en":{"title":"General nth-degree Bézier formula","subtitle":"Express an nth-degree Bézier curve with Bernstein basis functions and compute curve points from control points.","body":["An nth-degree Bézier curve is the weighted sum of control points P0 through Pn using Bernstein basis functions. At t=0 the curve starts at P0, at t=1 it ends at Pn, and the control-point weights vary smoothly in between.","Although the closed form is useful for understanding the mathematics, de Casteljau’s algorithm is usually easier to implement in Scratch because it avoids explicit binomial-coefficient logic."],"keyPoints":["Bézier curves are weighted sums of control points.","The endpoint property follows directly from the basis.","Use de Casteljau in Scratch for a simpler implementation."]},"lab":null,"baseLessons":[]},{"id":"p64","sourcePage":64,"chapter":"spline","tag":"第8講","title":"de Casteljau法","subtitle":"隣り合う点を線形補間し、点の数を4→3→2→1と減らして曲線上の一点を得る。","body":["de Casteljau法は、同じtで隣り合う制御点を線形補間し、その結果同士をさらに補間する手順です。4点なら最初に3点、次に2点、最後に1点が残ります。","同じ処理をx座標とy座標へ適用すれば、曲線上のB(t)を得られます。段階構造なのでScratchのリストとループに落とし込みやすい方法です。"],"keyPoints":[],"formulas":["Lerp(A,B,t) = (1-t)A + tB"],"en":{"title":"de Casteljau algorithm","subtitle":"Repeatedly interpolate neighboring points, reducing 4 → 3 → 2 → 1 until one Bézier point remains.","body":["De Casteljau’s algorithm linearly interpolates every neighboring control-point pair at the same t, then repeats the process on the new points. Four points become three, then two, then one final point.","Apply exactly the same recursion to x and y coordinates. Its repeated-list structure maps naturally to Scratch loops and temporary list storage."],"keyPoints":["Use the same t at every interpolation level.","Four control points reduce to one curve point.","The procedure is identical for x and y."]},"lab":null,"baseLessons":[]},{"id":"p65","sourcePage":65,"chapter":"spline","tag":"第8講","title":"定義 Spline Generate：N次ベジェ","subtitle":"制御点列をde Casteljau法で縮約し、t=0〜1を高密度サンプリングする。","body":["Spline Generateでは、Ipp cacheに切り出された1本分の制御点をN次ベジェ曲線として扱います。制御点がN+1個なら曲線はN次です。中間制御点は通常、曲線が通過する点ではなく形状を制御する点です。","各サンプルでは t を0から1まで進め、cache内の制御点を作業領域へコピーします。次に隣り合う2点を同じtで線形補間し、点数を N+1 → N → … → 2 → 1 と減らします。","r段目の点は P_i^(r)=(1-t)P_i^(r-1)+tP_(i+1)^(r-1) です。xとyへ同じ処理を行い、最後に残った P_0^(N) がそのtでのベジェ曲線上の点 B(t) になります。","Scratchでは作業リストを左から順に上書きするin-place縮約にできます。1段終わるごとに有効な点数を1つ減らせば、次数に依存しない同じループで任意個の制御点を処理できます。","例えば400点を事前生成するなら j=0〜399 に対して t=j/399 とし、得られたB(t)のx,yをSpline posへ交互に追加します。毎フレーム曲線を再生成せず、描画時はこの点列の必要部分だけを使います。","この方式では、Segment / LocalT、外側の仮想点、区間別の接線推定を使いません。制御点と曲線の関係そのものがN次ベジェの定義に置き換わります。"],"keyPoints":["N+1個の制御点からN次ベジェ曲線を生成","de Casteljau法は隣接点の線形補間を繰り返す","同一ループで任意次数へ対応","生成済み点列を毎フレーム再利用"],"formulas":["degree N = controlPointCount - 1","t = j / (sampleCount - 1)","P_i^(r) = (1-t) P_i^(r-1) + t P_(i+1)^(r-1)","B(t) = P_0^(N)","Spline pos += [B_x(t), B_y(t)]"],"en":{"title":"Definition: Spline Generate — N-degree Bézier","subtitle":"Reduce the control-point list with de Casteljau while densely sampling t from 0 to 1.","body":["Spline Generate treats the control points extracted into Ipp cache as one N-degree Bézier curve. N+1 control points define a curve of degree N. Intermediate control points usually shape the curve rather than lying on it.","For each sample, copy the control points into working storage and choose t in [0,1]. Interpolate every adjacent pair at the same t, reducing the point count from N+1 to N, then N-1, and so on until one point remains.","At level r, P_i^(r)=(1-t)P_i^(r-1)+tP_(i+1)^(r-1). Apply the same recurrence to x and y. The final point P_0^(N) is B(t), the point on the Bézier curve.","In Scratch the work list can be reduced in place from left to right. After each level, decrease the active point count by one. The same loop therefore supports any control-point count without degree-specific formulas.","For 400 precomputed samples, use j=0…399 and t=j/399, append Bx and By to Spline pos, then reuse that dense point list during rendering instead of regenerating the curve every frame.","This Bézier implementation does not use Segment/LocalT, virtual outer points, or segment-specific tangent estimation."],"keyPoints":["N+1 control points define an N-degree Bézier curve.","de Casteljau repeatedly interpolates neighboring points.","One degree-independent loop supports arbitrary control-point counts.","Generate dense samples once and reuse them during rendering."]},"lab":"spline","baseLessons":["l55","l56","l57","l58","l59","l60"]},{"id":"p66","sourcePage":66,"chapter":"spline","tag":"第8講","title":"de Casteljau法をIpp cacheで計算する","subtitle":"Ipp cache内の制御点を作業リストとして縮約し、de Casteljau法をScratchで実行する。","body":["Spline Setが1本分の制御点をIpp cacheへ切り出したあと、Spline Generateはその点列をde Casteljau法で縮約します。各段階で隣り合う点を補間し、必要な作業値だけを*Listに置きます。","曲線ごとにIpp全体を走査し直すのではなく、cacheへ分離しておくことで添字が単純になり、複数Splineを扱うときも処理範囲が明確になります。"],"keyPoints":[],"formulas":[],"en":{"title":"Running de Casteljau with Ipp cache","subtitle":"Use Ipp cache as the working control-point list and reduce it in-place with de Casteljau’s algorithm.","body":["After Spline Set extracts one curve into Ipp cache, Spline Generate reduces that cached control-point list with de Casteljau. Each level interpolates neighbors and keeps only the work values needed for the next level.","Working on one cached curve avoids repeatedly scanning the full Ipp list. Indices stay local and the processing boundary remains clear when several splines are stored together."],"keyPoints":["Ipp cache isolates one curve.","Reduce cached points level by level.","Local indices simplify multi-spline projects."]},"lab":null,"baseLessons":[]},{"id":"p67","sourcePage":67,"chapter":"spline","tag":"第8講","title":"ベジェ座標の具体例","subtitle":"4点ベジェでtを実際に代入し、de Casteljauの中間点がどのように収束するか確認する。","body":["具体例ではP0〜P3の4点を用意し、t=0.4など一つの値を固定して3段階の補間を計算します。最初の3点、次の2点、最後の1点を順番に図へ置くと、一般式が幾何的な補間の連鎖として見えるようになります。","Scratchでデバッグするときも、各段階の点を一時的にStampすると、どのレベルで計算が崩れているかを確認できます。"],"keyPoints":[],"formulas":[],"en":{"title":"Concrete Bézier-coordinate example","subtitle":"Substitute a concrete t value into a four-point Bézier example and follow the de Casteljau intermediates to the final point.","body":["Choose four control points P0-P3 and a concrete parameter such as t=0.4. Compute the three first-level interpolations, the two second-level interpolations, and then the single final point.","For debugging in Scratch, temporarily stamp the intermediate points. This shows exactly which interpolation level first diverges when the curve is wrong."],"keyPoints":["A numeric example makes the recursion visible.","Intermediate points should converge smoothly to one final point.","Stamping intermediates is an effective Scratch debugging method."]},"lab":null,"baseLessons":[]},{"id":"p68","sourcePage":68,"chapter":"spline","tag":"第8講","title":"定義 Direction from Points","subtitle":"atan（逆正接）だけでは象限が足りないため180度補正を足す","body":["Splineの端点コスチュームを線の向きへ合わせるため、2点から角度を求めます。","atan（逆正接）に傾きだけを入れると、反対向きの象限を区別できないので、x1がx2より小さいかどうかを0か1として180倍し、角度へ足しています。","推奨実装ではこの処理をDirection from Pointsという名前にすると、Atanという数学名だけより役割が伝わりやすくなります。"],"keyPoints":["Splineの端点コスチュームを線の向きへ合わせるため、2点から角度を求めます","atan（逆正接）に傾きだけを入れると、反対向きの象限を区別できないので、x1がx…","推奨実装ではこの処理をDirection from Pointsという名前にすると、Atanという数学名だけより…"],"formulas":["angle = 180*(x1 < x2) + atan（逆正接）((y1-y2)/(x1-x2))"],"en":{"title":"Definition: Direction from Points","subtitle":"Correct the missing quadrant information when using a slope-based atan calculation.","body":["A plain arctangent of slope cannot distinguish opposite directions. V2 adds a 180-degree correction based on the x ordering so endpoint costumes can align with the actual spline direction."],"keyPoints":["A plain arctangent of slope cannot distinguish opposite directions.","V2 adds a 180-degree correction based on the x ordering so endpoint costumes can align with the actual spline direction.","Check the formulas against the live values used by the implementation."]},"lab":null,"baseLessons":["l61"]},{"id":"p69","sourcePage":69,"chapter":"spline","tag":"第8講","title":"定義 Pen HSV","subtitle":"Stampの色体系をPenへ写し、カメラ Zoomで太さも変える","body":["Pen HSVGでは、Stamp側で使っているH、S、V、Ghostに近い入力をPenの色パラメータへ変換します。","Penの色相スケールはlooksのcolor effectと違うためHを2で割る形になっています。Sは100-S、明るさは100+V、transparencyはGです。","カメラを使う場合は線の太さにもZoomを掛けます。位置だけ拡大して線幅が同じままだと、世界全体をズームした見た目にならないためです。"],"keyPoints":["Pen HSVGでは、Stamp側で使っているH、S、V、Ghostに近い入力をPenの色パラメータへ変換します","Penの色相スケールはlooksのcolor effectと違うためHを2で割る形になっています","Sは100-S、明るさは100+V、transparencyはGです"],"formulas":["pen hue = (H + globalHue) / 2","pen saturation = 100 - S","pen 明るさ = 100 + V","pen size = bold * CameraZoom"],"en":{"title":"Definition: Pen HSV","subtitle":"Translate Stamp-like H/S/V/G controls into Pen settings and scale line width with camera zoom.","body":["Pen uses different color scales from Scratch's sprite effects, so the values are remapped. When camera zoom is active, line thickness is multiplied by zoom as well, preserving the appearance of a zoomed world."],"keyPoints":["Pen uses different color scales from Scratch's sprite effects, so the values are remapped.","When camera zoom is active, line thickness is multiplied by zoom as well, preserving the appearance of a zoomed world.","Check the formulas against the live values used by the implementation."]},"lab":null,"baseLessons":["l62"]},{"id":"p70","sourcePage":70,"chapter":"spline","tag":"第8講","title":"定義 Spline","subtitle":"他機能の拍Timerと異なるため、推奨実装では統一を推奨","body":["V2のSpline進行位置だけはScratch標準の「タイマー」を直接参照しています。一方、Easing、Effect、Particle、CameraはBPM換算した拍単位Timerを使うため、このままではBPM変更時にSplineだけ同期基準がずれます。","推奨実装ではSplineも変数Timerへ統一します。進行度を (Timer-t1)/(t2-t1) とすれば、他の機能と同じ拍単位で制御でき、音ハメの基準が一本化されます。"],"keyPoints":["ここだけ sensing timer を参照","Camera/Effect/Particleは変数Timer=拍を使う","BPMを変えるとSplineだけ同期基準が変わる可能性","推奨実装では変数Timerへ置換する方が一貫する"],"formulas":["index = 2*floor(400*((scratchTimer-t1)/(t2-t1)))"],"en":{"title":"Definition: Spline","subtitle":"Unify spline progress with the beat-based Timer used by the rest of the engine.","body":["V2's spline progress reads Scratch's raw timer while Camera, Effect, Particle, and Easing use beat Timer. A cleaner implementation uses the same beat-based progress formula everywhere so BPM changes do not desynchronize splines."],"keyPoints":["V2's spline progress reads Scratch's raw timer while Camera, Effect, Particle, and Easing use beat Timer.","A cleaner implementation uses the same beat-based progress formula everywhere so BPM changes do not desynchronize splines.","Check the formulas against the live values used by the implementation."]},"lab":null,"baseLessons":["l63"]},{"id":"p71","sourcePage":71,"chapter":"spline","tag":"第8講","title":"描画窓Length","subtitle":"進行位置の前後からLength分だけ取り、開始/終端で自動的に短くする","body":["Splineは曲線全体を常に描くのではなく、現在cursorからLength個分だけを描く窓として動きます。","最初はcursorが小さいので、過去側へLength分取れません。その場合cursor/2まで短くします。終端付近では800-cursor側が短くなるので、そちらへ合わせます。","このmin処理によって、線が始点から自然に伸び、終端へ近づくと描画窓がはみ出さず縮みます。"],"keyPoints":["Splineは曲線全体を常に描くのではなく、現在cursorからLength個分だけを描く窓として動きます","最初はcursorが小さいので、過去側へLength分取れません","その場合cursor/2まで短くします"],"formulas":["cursor = 2*floor(400*進行度)","drawLen = min(L, cursor/2, (800-cursor)/2)"],"en":{"title":"Draw-window Length","subtitle":"Draw only a limited number of samples around the current cursor and shrink the window near endpoints.","body":["The current progress selects a cursor in the 800-value x/y sample list. Draw length is clamped by the remaining samples on both sides, allowing a line to grow and finish without reading beyond the curve."],"keyPoints":["The current progress selects a cursor in the 800-value x/y sample list.","Draw length is clamped by the remaining samples on both sides, allowing a line to grow and finish without reading beyond the curve.","Check the formulas against the live values used by the implementation."]},"lab":null,"baseLessons":["l64"]},{"id":"p72","sourcePage":72,"chapter":"spline","tag":"第8講","title":"Shadow → Cap → Pen → Cap","subtitle":"1方向につき4段階で見た目を完成させる","body":["1方向のSpline描画は4段階です。まずdrawLen個の点へspline//shadowをStampして影やGlowを構成します。次に始点の方向をAtanで求め、spline//baseを端点キャップとして置きます。","その後Pen HSVGを設定し、点列を順番にPosへ渡しながらpen downで線を結びます。最後に終点でも角度を求め、もう1枚capを置いてpen upします。","Penだけでは端が角張るため、丸いコスチュームを端へ置く構造です。"],"keyPoints":["1方向のSpline描画は4段階です","まずdrawLen個の点へspline//shadowをStampして影やGlowを構成します","次に始点の方向をAtanで求め、spline//baseを端点キャップとして置きます"],"formulas":[],"en":{"title":"Shadow -> Cap -> Pen -> Cap","subtitle":"Build one visible spline direction in four rendering stages.","body":["First stamp shadow/glow elements along the selected samples, then place a start cap, draw the Pen line, and place an end cap. The cap costumes hide the hard ends that a Pen stroke alone would produce."],"keyPoints":["First stamp shadow/glow elements along the selected samples, then place a start cap, draw the Pen line, and place an end cap.","The cap costumes hide the hard ends that a Pen stroke alone would produce."]},"lab":null,"baseLessons":["l65"]},{"id":"p73","sourcePage":73,"chapter":"spline","tag":"第8講","title":"Mirror","subtitle":"MirrorSignを1 / -1に切り替え、必要に応じて原点対称を描画","body":["Spline本体ではMirrorSign（V2: 116）を1と-1に切り替え、xとyの両方へ掛けています。2回目は(-x,-y)となるため、1本目に対して原点対称のSplineが描かれます。","これはV2のデザインに合わせた演出であり、Splineの本質ではありません。汎用化する場合はmirrorを独立したオプションにし、必要なときだけ2本目を描く構成が分かりやすくなります。"],"keyPoints":["Spline本体ではMirrorSign（V2: 116）を1と-1に切り替え、xとyの両方へ掛けています","2回目は(-x,-y)となるため、1本目に対して原点対称のSplineが描かれます","これはV2のデザインに合わせた演出であり、Splineの本質ではありません"],"formulas":[],"en":{"title":"Mirror","subtitle":"Flip both x and y with MirrorSign to render an origin-symmetric copy.","body":["V2 alternates MirrorSign between 1 and -1 so the second pass draws (-x,-y). This is a style choice rather than a spline requirement, so a generalized engine should expose it as an optional mirror setting."],"keyPoints":["V2 alternates MirrorSign between 1 and -1 so the second pass draws (-x,-y).","This is a style choice rather than a spline requirement, so a generalized engine should expose it as an optional mirror setting."]},"lab":null,"baseLessons":["l66"]},{"id":"p74","sourcePage":74,"chapter":"spline","tag":"第8講","title":"ベジェ化したSplineの全体像","subtitle":"制御点 → de Casteljau → 点列生成 → 時間cursor → Shadow/Pen/Capまでを一つの流れで整理する。","body":["ベジェ化したSplineは、編集時に制御点をIppへ入れ、Spline Setで1本分をcacheし、Spline Generateで高密度点列を作ります。毎フレームは生成済み点列を再計算せず、Timerからcursorと描画窓だけを決めます。","描画時はShadowを重ね、始点Cap、Pen線、終点Capの順で仕上げ、必要ならMirrorで原点対称の2本目を追加します。生成と描画を完全に分けることが負荷と可読性の両方に効きます。"],"keyPoints":[],"formulas":[],"en":{"title":"Complete Bézier-based Spline pipeline","subtitle":"Connect control points, de Casteljau generation, sampled point lists, time cursor, and Shadow/Pen/Cap rendering into one spline pipeline.","body":["The Bézier-based spline pipeline stores editable control points in Ipp, extracts one curve with Spline Set, and generates a dense sample list ahead of time. Each frame reuses those samples and computes only the time cursor and draw window.","Rendering then layers Shadow, a start Cap, the Pen line, and an end Cap, with an optional mirrored pass. Separating generation from per-frame rendering improves both performance and readability."],"keyPoints":["Generate dense curve samples ahead of time.","Per-frame work should select and draw samples, not regenerate the curve.","Shadow/Pen/Cap and Mirror belong to the rendering phase."]},"lab":null,"baseLessons":[]},{"id":"p75","sourcePage":75,"chapter":"end","tag":"END","title":"定義 All","subtitle":"統合回は作らず、各講でAllへ1行ずつ追加する","body":["Allは各描画機能を一つにまとめる呼び出し口です。重要なのは統合そのものではなく、奥から手前へ描画する順序を固定することです。カメラ状態を先に確定し、背景、Effect、Particle、Spline、Text、最後にCover / Flashの順に重ねます。","V2のAllには空条件を利用したテンプレート部分がありますが、教材では用途名のあるON/OFF変数に置き換える方が読みやすくなります。"],"keyPoints":["奥から手前の順でStampする","Camera Updateは描画前に確定","Cover/Flashは最前面","V2のAll内にある空条件のParticle/BGはテンプレートスイッチ"],"formulas":[],"en":{"title":"Definition: All","subtitle":"Let All manage only back-to-front layer order.","body":["All should be a simple composition list: Background, Effect, Particle, Spline, Text, overlays, or whatever order the project requires. New systems add one line here instead of creating another centralized mega-definition."],"keyPoints":["All should be a simple composition list: Background, Effect, Particle, Spline, Text, overlays, or whatever order the project requires.","New systems add one line here instead of creating another centralized mega-definition."]},"lab":"dependencies","baseLessons":["l67"]},{"id":"p76","sourcePage":76,"chapter":"end","tag":"END","title":"定義一覧","subtitle":"講座で作成する主要定義を、引数・出力先・役割まで一覧で確認する。","body":["定義一覧は、コードを丸暗記するためではなく責務を確認するための索引です。List、Rotate Position、VFX Stamp、Position、Stamp、Easing、Camera、Text、Background、Effect、Particle、Spline、Allなどを一つの表で見直します。","実装時は「入力」「共有状態」「出力」「誰が呼ぶか」を確認し、同じ責務を複数定義へ重複させないようにします。"],"keyPoints":[],"formulas":[],"en":{"title":"Definition index","subtitle":"Review the main definitions created in the course, including arguments, outputs, and responsibilities.","body":["The definition list is an index of responsibilities rather than something to memorize. Review List, Rotate Position, VFX Stamp, Position, Stamp, Easing, Camera, Text, Background, Effect, Particle, Spline, All, and the helper definitions used by them.","When implementing a definition, check its inputs, shared state, outputs, and callers. Avoid duplicating the same responsibility in several places."],"keyPoints":["Use the list as a responsibility map.","Check inputs, outputs, shared state, and callers.","One responsibility should have one clear owner."]},"lab":null,"baseLessons":[]},{"id":"p77","sourcePage":77,"chapter":"end","tag":"END","title":"完成チェック","subtitle":"各定義の責務・数式・V2固有仕様を区別して理解するための確認事項","body":["完成度の高いエンジンでは、各定義の責務が明確であることが重要です。入力、共有状態、出力を区別し、数式は「何を入力すると見た目がどう変わるか」と対応づけます。","V2固有のSize hack、負の時刻を使うCover、*Listを一時メモリとして再利用する方法は、機能の本質ではなく実装上の工夫です。教科書では原理を先に示し、V2の番号やハックは補足として後から対応づけます。","推奨実装では、イントロ終了条件を明示し、BGの境界値を区分関数で固定し、Particleの疑似乱数を1式ハッシュへ置き換え、Splineの時間単位を拍Timerへ統一します。"],"keyPoints":["各定義を「入力・内部状態・出力」に分けて捉える","数式は図・式・見た目の変化を対応づける","V2固有ハックとエンジン本体の原理を分離する"],"formulas":[],"en":{"title":"Final verification","subtitle":"Separate each definition's responsibility, formulas, and V2-specific workarounds.","body":["A robust engine is easier to understand when inputs, shared state, outputs, and rendering responsibilities are explicit. Keep core principles separate from V2-specific hacks, verify boundary times, and prefer clear deterministic behavior over hidden state."],"keyPoints":["A robust engine is easier to understand when inputs, shared state, outputs, and rendering responsibilities are explicit.","Keep core principles separate from V2-specific hacks, verify boundary times, and prefer clear deterministic behavior over hidden state."]},"lab":null,"baseLessons":["l68"]}],"definitions":[{"id":"list","name":"*List","ja":"共有ワークメモリ。定義間の値受け渡しと一時計算に使う。","en":"Shared working memory used for passing values and temporary calculations.","deps":[],"usedBy":["rotmat","easing","camera","position","text","background","effect","particle","spline"],"lessons":["p05"]},{"id":"rotmat","name":"Rotate Position / RotMat","ja":"2次元座標を指定角度だけ回転し、結果を*Listへ出力する。","en":"Rotates a 2D coordinate by an angle and writes the result to *List.","deps":["list"],"usedBy":["position","spline"],"lessons":["p08"]},{"id":"vfx","name":"VFX Stamp","ja":"色・明るさ・透明度などを設定して1回Stampする。","en":"Applies visual effects and performs one stamp.","deps":["list"],"usedBy":["stamp","effect"],"lessons":["p09"]},{"id":"position","name":"Position / Pos","ja":"World座標をCamera差分・回転・Zoomで画面座標へ変換する。","en":"Transforms world coordinates into screen coordinates using camera offset, rotation, and zoom.","deps":["rotmat","camera","list"],"usedBy":["stamp","spline"],"lessons":["p10","p25"]},{"id":"stamp","name":"Stamp","ja":"時間条件・Position・VFXをまとめる共通描画入口。","en":"The common drawing entrance that combines timing, Position, and VFX.","deps":["position","vfx","timer"],"usedBy":["text","background","effect","particle","spline"],"lessons":["p11","p12"]},{"id":"timer","name":"Timer","ja":"Scratchの秒をBPMで拍へ変換した共通時間軸。","en":"A beat-based timeline converted from Scratch seconds using BPM.","deps":[],"usedBy":["easing","camera","background","effect","particle","spline"],"lessons":["p14","p15","p20"]},{"id":"easing","name":"Easing","ja":"時間を0〜1へ正規化し、曲線を掛けて任意の値域へ戻す。","en":"Normalizes time to 0-1, applies a curve, and maps it into any value range.","deps":["timer","list"],"usedBy":["camera","text","background","effect","particle","spline"],"lessons":["p16","p17","p18"]},{"id":"camera","name":"Camera / Shake","ja":"編集値にShakeを加え、Positionが読む最終Camera状態を作る。","en":"Combines editable camera values with shake into the final camera state used by Position.","deps":["timer","easing","list"],"usedBy":["position","text","background","effect","particle","spline"],"lessons":["p21","p22","p23","p24","p25"]},{"id":"text","name":"Text","ja":"現在時刻の文字状態を計算し、過去サンプルを重ねてBlurを作る。","en":"Computes text state at a time and layers historical samples to create motion blur.","deps":["easing","camera","stamp"],"usedBy":["all"],"lessons":["p27","p28","p29","p30"]},{"id":"background","name":"Background","ja":"スクロール位置と必要タイル数を分離して背景を反復描画する。","en":"Separates scroll position from tile count to render repeating backgrounds.","deps":["timer","camera","stamp"],"usedBy":["all"],"lessons":["p33","p34","p35","p37"]},{"id":"effect","name":"Effect","ja":"連番コスチュームを時間からフレーム番号へ変換して再生する。","en":"Maps time to numbered costume frames and renders reusable sequence effects.","deps":["timer","easing","stamp"],"usedBy":["all"],"lessons":["p40","p41","p42","p43","p44","p45","p46"]},{"id":"particle","name":"Particle","ja":"粒子を保存せず、整数indexと現在時刻から状態を再構成する。","en":"Reconstructs particle state from integer indices and current time instead of storing clones.","deps":["timer","easing","stamp"],"usedBy":["all"],"lessons":["p53","p54","p56","p57","p58"]},{"id":"spline","name":"Spline","ja":"制御点から高密度点列を事前生成し、Pen/Stampで一部分を描画する。","en":"Precomputes dense curve samples from control points and renders a selected portion with Pen/Stamp.","deps":["timer","easing","rotmat","camera","position","stamp"],"usedBy":["all"],"lessons":["p60","p61","p62","p65","p68","p69","p70","p71","p72","p73"]},{"id":"all","name":"All","ja":"描画機能の奥→手前の順番だけを管理する最終合成定義。","en":"Final composition definition that manages only back-to-front draw order.","deps":["background","effect","particle","spline","text"],"usedBy":[],"lessons":["p75","p77"]}],"glossary":[{"term":"BG","ja":"Background。背景描画系の略称。","en":"Background; shorthand for the background rendering system."},{"term":"BPM","ja":"Beats Per Minute。1分あたりの拍数。Timerの秒→拍変換に使う。","en":"Beats Per Minute; used to convert seconds into beat-based Timer values."},{"term":"HSV","ja":"Hue / Saturation / Value。色相・彩度・明度。","en":"Hue / Saturation / Value."},{"term":"VFX","ja":"Visual Effects。色・明るさ・透明度や連番演出などの視覚効果。","en":"Visual Effects, including color, brightness, transparency, and sequence effects."},{"term":"ID","ja":"Identifier。EffectやParticleなどの種類を識別する番号・値。","en":"Identifier used to select an effect, particle type, or other variant."},{"term":"Ipp","ja":"Splineの制御点を x,y,x,y,… と並べ、カンマで曲線を区切る入力リスト。","en":"Spline control-point input list storing x,y pairs and comma separators between curves."},{"term":"Bezier / Bézier","ja":"制御点から滑らかな曲線を作る代表的なパラメトリック曲線。","en":"A parametric curve defined by control points and commonly evaluated with Bernstein basis or de Casteljau."},{"term":"de Casteljau","ja":"隣り合う点の線形補間を繰り返してベジェ曲線上の点を求める方法。","en":"A recursive interpolation algorithm for evaluating a Bézier curve."}]};
